window.__TR__.he = {"b67fd90b":"מסוף האוטובוסים BSÍ → Þingvellir","f5b7eaca":"🧵 שלושה שמות לשמור בכיס","30f516f0":"יוצאים מ-BSÍ — לא צריך חלון בשביל זה.","3aa9a375":"עמק אחד — **Mosfellsdalur, עמק הספרות שלי** — קושר יחד כסף ויקינגי טמון, ציור שנפסל ומדליית נובל, לאותו קטע דרך של עשרים דקות.","8bab1a36":"תשמרו את שלושת השמות בכיס. עד שנצא מהעמק, תדעו למה הציור, הבירה והספר מגיעים כולם בסוף לאותו בית.","6fae6b36":"**Kjarval** — הצייר. הסיפור שלו פותח את הסיור בעוד שתי דקות — ו**תמונת המזבח המלאה בבני אלפים שהכנסייה סירבה לברך** תחכה לנו בעמק בהמשך הדרך.","e87ff25f":"**Tómas** — המבשל. הוא קרא למבשלה שלו על שם **Egill Skallagrímsson**, לוחם-משורר ויקינגי שהיה מסוגל לרוקן אולם שלם מאלכוהול — ושבזקנתו **טמן הון בכסף** בעמק שנעבור בו בתוך שעה.","e7cb3d3b":"**Halldór** — הסופר. הוא גדל **באותו עמק בדיוק**, זכה ב**פרס נובל לספרות** היחיד של איסלנד — וכשהכנסייה זרקה לפח את תמונת המזבח שנפסלה של Kjarval, **Halldór קנה אותה ונתן לה קיר בבית שלו.** היא תלויה שם עד היום.","320d217b":"הצייר; הסיפור שלו פותח את הסיור","865297e1":"המבשל שקרא לבירה שלו על שם ויקינג","c106c0fb":"נער החווה שזכה בנובל","158072cb":"לוחם-המשורר הוויקינגי שמחבר בין המבשלה לעמק","3f43246c":"עמק הספרות שבו כל החוטים נקשרים","b12f0cc5":"Jóhannes Sveinsson Kjarval","4d1091fa":"תסתכלו שמאלה, בשעה 9 — פארק Klambratún.","aaebc12d":"רוב האמנים נוסעים מסביב לעולם כדי למצוא השראה. Kjarval מצא מדינה שלמה ב**אדמה שמתחת למגפיים שלו** — ואז החזיר אותה, קנבס אחר קנבס.","ca97792a":"באיסלנד הנוף מחזיר מבט — ולפעמים גם מגיש תלונה לבישוף.","66ce74a3":"חלופה למזג אוויר גרוע (אם הבניין לא נראה): \"אם אתם לא מצליחים לזהות את הבניין האפור במזג אוויר כזה, אל תדאגו — Kjarval פשוט היה מצייר במקומו את מזג האוויר. הוא בדרך כלל עשה בדיוק את זה.\"","680aeff2":"נולד ב-**15 באוקטובר 1885** בחווה **Efri-Ey** ב-**Meðalland**, בדרום איסלנד — **התשיעי מתוך 13 ילדים** (להורים שלו בבירור היה כוח סוס). נשלח לאומנה במזרח, ל-**Geitavík** שב-**Borgarfjörður eystri**, ושם הפיורד עדיין קורא לו **\"Jói í Geitavík.\"** עני מכדי לקנות צבעים, הוא צייר ב**דם עגלים, פיח וצבע צמר** — ואז יצא לים.","7e85f233":"אנשי הצוות ראו את הסקיצות שלו, **העבירו את הכובע**, ואיגוד הדייגים השלים את הסכום. **1911**: הוא ניסה את **לונדון** — ה**אקדמיה המלכותית טרקה לו את הדלת**. הסירוב היה בעצם שינוי כיוון: **קופנהגן** וה**אקדמיה המלכותית הדנית** (סיים ב-**1917**).","e57031f5":"כשחזר הביתה הוא צייר את איסלנד כמו שאף אחד לא צייר לפניו — כרע על ברכיו מעל ה**טחב והלבה, שלושה אינצ'ים מהאף שלו**, ונשבע שהוא רואה **בני אלפים ועם נסתר** בתוך הסדקים. (באיסלנד זו לא אבחנה. זו קריירה.)","e11bd479":"ב-**1968** הוא מסר לעיר **חלק עצום מכל מה שהיה לו** — אוסף Kjarval במוזיאון מגיע ל**אלפי עבודות** — והוא מת **כשכמעט כלום כבר לא היה שלו.** הגוש האפור הזה ב-Klambratún הוא **Kjarvalsstaðir**, **מוזיאון האמנות הראשון באיסלנד שנבנה מלכתחילה בשביל זה** (1973); ומאז **1995** הפרצוף שלו על שטר ה-**2,000 קרונה** — הדייג היחיד בהיסטוריה ש**קודם לדרגת הילך חוקי.**","591caf4f":"צייר איסלנדי פורץ דרך","e7e3c451":"המוזיאון שלו, הבניין האפור בפארק","62a7dc2e":"הפארק ב-Reykjavík שבו הוא עומד","88b713ee":"המחוז בחוף הדרומי שבו הוא נולד","a8574055":"הפיורד המזרחי שבו הוא גדל אצל משפחה אומנת","4362caa4":"חוות האומנה במזרח; הפיורד עדיין קורא לו \"Jói í Geitavík\"","73a25af7":"המטבע של איסלנד; ברבים *krónur*","5b6df0dc":"🏢 Ölgerðin Egill Skallagrímsson","999bb608":"תסתכלו ימינה, בשעה 3 — מבשלת Egils.","a907a859":"Tómas לא הצליח לברוח מהיובש. הוא פשוט **שרד אותו** — 74 שנה על כמעט-בירה ועל אישור מלכותי.","e0692afe":"כשקוראים לחברה על שם ויקינג, לא מצייתים לחוקים. פשוט מחכים שהם ייגמרו.","01babc03":"חלופה למזג אוויר גרוע (אם המבשלה לא נראית): \"אם הערפל בלע את המבשלה מימין, זה בסדר גמור — חברה ששרדה 74 שנות יובש תשרוד גם בוקר אפור אחד.\"","49b435f4":"נוסדה ב-**17 באפריל 1913** בידי **Tómas Tómasson** בשני חדרי שינה במרתף של בית שכור ב-Reykjavík — בהתחלה רק **תמצית לתת של 1% אלכוהול** — וקיבלה את שמה מ-**Egill Skallagrímsson**, לוחם-המשורר שפעם חרז את עצמו החוצה מגרדום התליין (ה-*Höfuðlausn*, \"פדיון הראש\") והיה מסוגל להשכיב אולם שלם מתחת לשולחן. מיתוג שאפתני.","5c294737":"שנתיים אחר כך איסלנד אוסרת על **כל האלכוהול** (1915) — אז Tómas מפליג ל**קופנהגן ולגרמניה (1915–17) כדי ללמוד בישול בירה בכל זאת**, ומתאמן על מוצר שהמדינה שלו בדיוק הוציאה מחוץ לחוק. היין חוזר בהדרגה ב-**1922**, המשקאות החריפים ב-**1935**, אבל **הבירה נשארת לא חוקית עד 1989**. דווקא הבירה, כי היא נתפסה כ**דנית** — וללגום לאגר דני בזמן שנאבקים בדנמרק על עצמאות הרגיש כמו בגידה.","00769b98":"אז Ölgerðin מרמה קצת: מבשלת את **Egils Pilsner ומשאירה אותו ממש מתחת לתקרה החוקית של 2.25%** — בירה שטכנית לא הייתה בירה. פרצה בחוק בתוך כוס. (ה-**Appelsín** הכתום, שטובעים אותו במאלט בכל חג המולד, הגיע מאוחר יותר — **1955**.)","d7417a15":"שיא האירוניה מגיע ב-**1926**: אחרי ביקור ממלכתי של המלך **כריסטיאן העשירי**, Ölgerðin זוכה בזכות לקרוא לעצמה **\"המבשלה המלכותית\"** — ברכה מלכותית דנית, במדינה שאוסרת חצי-חצי על בירה בגלל שהיא דנית מדי.","132c3915":"הבירה האמיתית חזרה ב-**1 במרץ 1989** — היום זה **Bjórdagurinn, \"יום הבירה.\"** Egils לא נלחמה על מקום על המדף; המדף כבר היה שלה.","2ed28b52":"המבשלה הכי מוכרת באיסלנד, נוסדה ב-1913","cf7eb5d9":"לוחם-המשורר הוויקינגי שהמבשלה נקראת על שמו","528c10d7":"המשקה הכתום שלהם, שטובעים אותו במאלט בכל חג המולד","052ce5af":"המייסד","b2513507":"\"יום הבירה\", 1 במרץ, היום שבו הבירה חזרה להיות חוקית","861f6bf3":"🏞️ Elliðaárdalur","93a72615":"תסתכלו ימינה, בשעה 2 — Elliðaárdalur.","5608f08b":"נראה כמו פארק להוצאת כלבים. בפועל זה המקום שממנו הבירה **מקבלת אוכל, מים וחשמל — וגם למדה בפעם הראשונה להתווכח בפומבי.**","489da628":"Reykjavík לא קיבלה נהר של גלויות. היא קיבלה **אולר שוויצרי.**","10e7afdb":"חלופה למזג אוויר גרוע (אם העמק לא נראה): \"אם הגשם הסתיר את העמק מימין, פשוט תדמיינו קניון נהר ירוק שעושה חמש עבודות בבת אחת — ארוחת ערב, מים, חשמל ופרלמנט — אי שם בתוך העכירות.\"","42b07b59":"תכירו את ה-**Elliðaá** — אחד הנהרות היחידים בעולם שעוברים בעיר בירה ויש בהם **מהלך טבעי של סלמון אטלנטי**. בערך **2,500** דגים דוחפים כל קיץ במעלה הזרם, חולפים על פני הרצים, כדי להטיל ביצים — והעיר כל כך התאהבה שהיא **קנתה את כל הנהר ב-1906**. (העיר שלכם קונה פארקים. אנחנו קנינו נהר.)","273202de":"**מי הברז הצלולים** שהמלון שלכם לא מפסיק להתגאות בהם? מעיינות באותו אגן ניקוז בדיוק, למעלה ליד האגם **Elliðavatn** — העיר שאבה כאן מי שתייה בפעם הראשונה ב-**1909**.","85ca7714":"והאורות? ב-**1921** סכרו אותו בשביל **Elliðaárstöð** — תחנת הכוח הראשונה של **Reykjavík** ותחנת הכוח ההידרואלקטרית **השנייה של איסלנד**, שהופעלה בידי המלך **כריסטיאן העשירי** בכבודו ובעצמו ב-**27 ביוני 1921** ועדיין עובדת מאה שנה אחר כך.","fb21b37c":"במעלה הזרם, על לשון יבשה נמוכה בתוך **Elliðavatn** ששמה **Þingnes**, ישב ה-**Kjalarnesþing** — **האספה הראשונה של איסלנד**, שהקים **Þorsteinn Ingólfsson** (בנו של המתיישב הראשון) עוד לפני ה-**Alþingi** הלאומי של שנת **930**. השטח הישן נמצא היום **חלקית מתחת למים**. איסלנדי מאוד: להמציא דמוקרטיה ואז להציף אותה. (עוד על פרלמנטים בקרוב.)","ce0609e6":"וגם החום. המים החמים של Reykjavík לא התחילו מהרי געש, הם התחילו **בתוך העיר** — **שדות בטמפרטורה נמוכה ב-Laugarnes וכאן ב-Elliðaárdalur**, ובנוסף **Mosfellsbær** מחוץ לעיר. הבארות האלה עדיין פועלות, ומעבירים שכונות במכוון ממקור אחד לשני **כדי לתת למאגר שמתחת לעיר לנוח.** (כן, גם לאדמה מגיעה שכיבה קטנה.)","5d1402bd":"יש אפילו סיבה כימית לזה שהמקלחת מתנהגת כאן מוזר: המים מהבארות של **Laugarnes** **עשירים בסיליקה**, שנשקעת על הברזים והאריחים כשהמים מתקררים, ואילו המים מ-**Nesjavellir ומ-Hellisheiði** הם מי תהום מחוממים ו**דלים בסיליקה.** אותו ברז, גיאולוגיה אחרת.","3f1e2bb8":"עמק הנהר מימין שמאכיל, משקה ומספק חשמל לעיר","a28ad182":"הנהר עצמו, עם מהלך סלמון אטלנטי טבעי משלו","dcd4ae54":"האגם במעלה הזרם, שממנו נובעים מי השתייה של העיר","6686e3f2":"לשון היבשה הנמוכה באגם הזה, שבה ישבה האספה הראשונה של איסלנד","a23cff17":"בנו של המתיישב הראשון, שהקים את האספה ההיא","7186d440":"⛰️ הר Esja","e4d4323f":"תסתכלו שמאלה וקדימה — הקיר הארוך והמפוספס של Esja.","f6005ef3":"כהה = חם, בהיר = קפוא. מבט אחד למעלה ואתם קוראים **11 עידני קרח** לפני שהרמזור מתחלף.","daa6a72f":"תושבי Reykjavík לא בודקים את אפליקציית מזג האוויר — הם בודקים אם עדיין רואים את Esja. אם Esja נעלמה, הטלפון שלכם הוא הבעיה הכי קטנה שלכם.","fd2047d1":"חלופה למזג אוויר גרוע (אם Esja לא נראית): \"אם אתם לא רואים עכשיו את Esja בקו הרקיע, מזל טוב — ההר בדיוק נתן לכם את תחזית מזג האוויר של היום, והיא 'ממש לא'.\"","12b3bf72":"**Esja** התרוממה לפני **3.2 עד 1.8 מיליון שנה**, כשהקצה המערבי הוא העתיק ביותר — היא נשחקת יותר זמן ממה שבני אדם בכלל קיימים, והיא לא הר אחד אלא **רכס וולקני** שלם.","eef0ed83":"הפסים הם אקלים שאפשר לקרוא ישר מהמושב: **בזלת כהה** זרמה בתקופות **חמות ונטולות קרח** והתקררה בשקט; **móberg בהיר** (טוף) הוא לבה שהתחילה עם קרחון והפסידה — התנפצה לרסיסים מתחת לקרח.","4e7dd2d2":"תספרו את הרצועות ואתם סופרים גלי קור: גיאולוגים קוראים שם **לפחות 11 עידני קרח נפרדים**. זה גורם לחורף הזה להיראות כמו חימום לפני אימון.","5c1445d6":"הפסגה האמיתית היא **Hábunga (914 מ')** — שכמעט אף אחד לא טורח להגיע אליה. הלהיט האמיתי הוא **Þverfellshorn (בערך 780 מ')**, שם סלע ענק בשם **Steinn**, בערך **200 מ' מתחת לפסגה**, הוא נקודת החזרה הרשמית של \"מספיק קרוב, תצלמו סלפי\". נגעתם בסלע, טיפסתם על Esja. אנחנו לא שואלים שאלות.","a956c06b":"הרכס המפוספס בקו הרקיע שלפנינו; רכס וולקני שלם, לא הר אחד","5c474d83":"הפסגה האמיתית, 914 מ', שכמעט אף אחד לא טורח להגיע אליה","8578e2e8":"הפסגה שאליה כולם באמת מטפסים, בערך 780 מ'","5473d2cf":"הסלע 200 מ' מתחת לפסגה, שבו המטיילים מסתובבים חזרה בשביל הסלפי","8b1f3bfa":"הסלע הבהיר: לבה שנלחמה בקרחון והתנפצה מתחת לקרח","94b3cff7":"⚖️ Kjalarnesþing","f9d4bf96":"תסתכלו שמאלה, בשעה 9 — מעבר ל-Kollafjörður אל Kjalarnes, למרגלות Esja, עשרה קילומטרים מכאן. אנחנו פונים מזרחה עוד לפניו.","15d0e5f0":"המופע הגדול ב-Þingvellir היה בעצם העונה השנייה. Kjalarnes כתב את פרק הפיילוט — ולא קיבל שום קרדיט.","96f494d5":"Kjalarnes הכין את שיעורי הבית. Þingvellir לקח את הקרדיט, את התהילה ואת התיירים.","282bff3d":"חלופה למזג אוויר גרוע (אם אתר האספה לא נראה): \"ממילא אין שם מה לראות — הפרלמנט הראשון לא השאיר שיש ולא השאיר חורבות, רק את העובדה שלפני אלף שנה איסלנדים עמדו במזג אוויר בדיוק כזה והתווכחו על החוק בקול רם.\"","1b428edd":"**Þorsteinn Ingólfsson** — בנו של **Ingólfur Arnarson**, המתיישב הראשון של איסלנד — הקים את ה-**Kjalarnesþing** שם על הכף בערך בשנת **900 לספירה**, ו**מקובל לומר שזו האספה הקדומה ביותר במדינה**, דור שלם לפני ה-Alþingi הלאומי של **930**. המסורת אפילו מייחסת ל-Þorsteinn את **הקדשת** הפרלמנט הלאומי המאוחר יותר — כלומר בנו של המייסד לא רק בנה את אב הטיפוס, הוא גם בירך את ההמשך. ה-þing עבר בהמשך למטה, ל-**Þingnes ליד Elliðavatn** (לשון היבשה שחלפנו על פניה), והמשיך להתכנס עד לתוך **שנות ה-1200**.","51d09e31":"כדי לכתוב חוקים כמו שצריך, המנהיגים המקומיים לא המציאו את הגלגל מחדש — הם שלחו איש אחד, **Úlfljótr**, ל**נורווגיה לשלוש שנים** כדי ללמוד את חוק ה-**Gulating** ולהתאים אותו לבית. הוא חזר עם **חוק Úlfljótur**, **קובץ החוקים הראשון** של איסלנד — אבל עם טוויסט רדיקלי אחד שלנורווגים לא היה: פרלמנט **בלי מלך**. החלק הזה היה כולו שלהם.","f5c3bfce":"שום דבר לא נכתב — לאיסלנד לא הייתה כתיבה ראויה לשמה — ולכן **Úlfljótur נשא את כל קובץ החוקים הביתה בתוך הראש שלו**, וחזר בערך ב-**921** אחרי **שלושה חורפים** בחוץ. מה שהוא דקלם נקרא **Úlfljótslög**, החוק העתיק ביותר שיש למדינה הזאת, והוא אומץ עם הקמת ה-**Alþingi ב-930**. Úlfljótur סיפק את הטקסט. Þingvellir סיפק רק את האולם.","2f5b0560":"**למנסח החוקים הראשון של איסלנד יש אגם, חווה וכנסייה שנושאים את שמו** — **Úlfljótsvatn**, המים של Úlfljótur — וכמעט אף אחד לא עוצר באף אחד משלושתם. (הכנסייה היא הכיפית: תפתחו מדריך טיולים והיא נבנתה ב-**1914**, תפתחו את פנקס המורשת הלאומי והיא נבנתה ב-**1863**, בידי **Eyjólfur Þorvarðsson**, *forsmiður frá Bakka*. כששני תאריכים לא מסכימים, קחו את זה שיש בו נגר.)","69412d41":"המשפט המפורסם **\"með lögum skal land byggja\"** — בחוקים תיבנה הארץ — נתלה על הצוואר של Úlfljótur כל הזמן, ו**הוא כמעט בוודאות מעולם לא אמר אותו.** הוא הגיע לאיסלנד עם **Járnsíða**, קובץ חוקים של מלך נורווגי שנכפה בין **1271 ל-1274**, בנוסח המלא יותר **\"með lögum skal land vort byggja en eigi með ólögum eyða\"**, והניסוח מגיע במקור מה-**Frostaþingslög** הנורווגי. כלומר הוא **צעיר מדי בערך בשלוש מאות וחמישים שנה** מכדי להיות שלו.","02a5631e":"האספה שהתכנסה שם על הכף, הקדומה ביותר במדינה, בערך בשנת 900 לספירה","b535ec77":"בנו של המתיישב הראשון, שהקים אותה","b5765b20":"אביו, המתיישב הראשון של איסלנד","6271f9c9":"האיש שנשלח לנורווגיה לשלוש שנים כדי להביא את קובץ החוקים הראשון של איסלנד","71dedbaa":"האגם שאליו עברה האספה בהמשך","75436d33":"החוק הנורווגי שהוא למד והתאים","555d1d0d":"🎵 Mosfellsbær","eeed2753":"מסביבנו מכל הכיוונים — Mosfellsbær.","8dbe239b":"עיירה בגודל כזה לא אמורה להצליח להוציא אפילו אמן עולמי אחד. Mosfellsbær הוציאה שניים — פסנתר שקט כמו לחישה ובלוז של אצטדיונים, מאותה חלקת טחב.","d85c3e2f":"שני אמנים, עיירה קטנה אחת, אפס רוגע.","0b7cbbdf":"חלופה למזג אוויר גרוע (אם העיירה לא נראית): \"אתם לא צריכים לראות את Mosfellsbær כדי לשמוע אותה — עיירת פרברים בגודל כזה ייצאה שתי להקות מפורסמות בעולם, אז בואו פשוט נגביר את המוזיקה וניתן לערפל לטפל בצד הוויזואלי.\"","917673e4":"**Ólafur Arnalds**, שנולד כאן ב-**1986**: **זכה בפרס BAFTA TV Craft של 2014** על הפסקול לסדרה *Broadchurch* של ITV, וחטף גם **שתי מועמדויות לגראמי** בטקס של 2021. בפרויקט *Island Songs* שלו (2016) הוא כתב **שבעה שירים בשבעה שבועות בשבעה מקומות** ברחבי איסלנד — אחד מהם, *\"Particles\"*, עם **Nanna Bryndís** מ-Of Monsters and Men.","6af2474a":"🎵 *מתנגן עכשיו — \"Particles\", Ólafur Arnalds בשיתוף Nanna Bryndís Hilmarsdóttir*","e6b5d7bd":"בקצה הרועש של הווליום: **Kaleo**, להקת הבלוז-רוק שקמה כאן ב-**2012**, שהשיר שלה *\"Way Down We Go\"* הגיע ל**מקום הראשון** במצעד האלטרנטיבי האמריקאי. השיר שלהם *\"Vor í Vaglaskógi\"* הוא גרסת כיסוי מעושנת לקלאסיקה איסלנדית על יער בצפון.","7a921239":"🎵 *מתנגן עכשיו — \"Vor í Vaglaskógi\", Kaleo*","c88a7b63":"עיירת הפרברים שסביבנו, בערך 13,700 תושבים","585a48de":"המלחין שנולד כאן ב-1986, הקצה השקט של כפתור הווליום","f6beddc7":"להקת הבלוז-רוק שקמה כאן ב-2012, הקצה הרועש","61083f02":"מ-Of Monsters and Men; היא שרה ב-Particles","949e34a8":"השיר של Kaleo, גרסת כיסוי לקלאסיקה איסלנדית על יער בצפון","1beff30d":"🪶 Mosfellsdalur","03baddb8":"מסביבנו מכל הכיוונים — Mosfellsdalur.","4de43cad":"הון טמון שאף אחד מעולם לא מצא, ופרס נובל שנכתב חמש דקות נסיעה משם.","7da1d7f3":"איש אחד הסתיר את ההון שלו. השני השאיר את שלו על המדפים.","55db548c":"חלופה למזג אוויר גרוע (אם העמק לא נראה): \"אם אתם לא רואים את העמק, קחו נחמה — גם אלף שנה של ציידי אוצרות לא הצליחו למצוא בו את הכסף של Egill, אז אתם בחברה ריקת ידיים בדיוק כמוכם.\"","8606b70d":"**הכסף (מתוך הסאגה של Egill):** בזקנתו לוחם-המשורר **Egill Skallagrímsson** — שישב על שתי תיבות כסף שקיבל במתנה מ**המלך Æthelstan מאנגליה** (אותו Egill שהמבשלה שם בעיר נקראת על שמו) — התחמק באמצע ה-Alþingi עם הכסף, סוס ושני עבדים. הסוס חזר. Egill חזר. העבדים והכסף לא — הוא הרג אותם כדי לשמור את המקום בסוד. אלף שנה של ציידי אוצרות אחר כך, התוצאה: **אפס**. (סאגה, לא חפירה ארכיאולוגית — תתייחסו לזה כאל אגדה.)","4fec4dac":"**החפירה:** ארכיאולוגים חפרו לא רחוק מכאן ב-**Hrísbrú**, שם, לפי הסאגה, הועברו בהמשך עצמותיו של Egill לכנסייה שבנו צאצאיו.","a96ce587":"**הנובל:** נולד בשם **Halldór Guðjónsson** ב-**1902**, וגדל מגיל שלוש בחווה **Laxnes** ממש כאן בעמק — וכשהיה צריך שם סופר, **הוא לקח את זה של החווה**. **פרס נובל לספרות, 1955**, בעיקר על ***Sjálfstætt fólk*** (*אנשים עצמאיים*).","4bfdebe9":"הבית שלו, **Gljúfrasteinn**, מחכה ממש בהמשך הכביש — זו התחנה הבאה שלנו.","d4e1d44e":"🎬 בהמשך העמק יושבת חוות הרכיבה המשפחתית ב-**Laxnes** — עם קורות חיים על המסך טובים יותר משל רוב השחקנים העובדים: היא סיפקה את **הסוסים האיסלנדיים ל*Game of Thrones*** , כולל הסוסים ש**Arya Stark** ו**הכלב** רכבו עליהם בסצנות שצולמו ב-Þingvellir.","64d13428":"העמק שסביבנו: כסף טמון בקצה אחד, נובל בקצה השני","af493aad":"נולד ב-1902, גדל בעמק הזה, חתן פרס הנובל היחיד של איסלנד","ea1cc859":"הבית שלו, היום מוזיאון, ומכונת הכתיבה עדיין על השולחן","4c63d468":"אנשים עצמאיים, הרומן שעליו זכה בנובל של 1955","b2a065cd":"Egill Skallagrímsson, לוחם-המשורר שטמן כאן את הכסף שלו","96a89f0f":"אתר החפירה בעמק הזה, שאליו לפי הסאגה הועברו עצמותיו של Egill","cd1d0370":"🪶 Gljúfrasteinn","478188c5":"על כביש 36, במעלה העמק — Gljúfrasteinn, הבית הלבן ליד הנהר.","d2551b1a":"הנובל היחיד של איסלנד חזר הביתה לעמק שקט — לבית שמשמש גם כגלריה הקטנה במדינה לאמנות שנפסלה.","a4dd4c64":"נובל על המדף, תמונת מזבח פסולה על הקיר — Gljúfrasteinn הוא המקום שבו איסלנד שומרת את הדברים ששומרי הסף טעו לגביהם.","61e3d750":"חלופה למזג אוויר גרוע (אם הבית לא נראה): \"אם העמק מכוסה בערפל, לא נורא — האיש שגר בבית הזה בילה חמישים שנה בלהוכיח שלא צריך לעזוב עמק גשום כדי לזכות בפרס נובל.\"","cf8f8ca1":"**Halldór Laxness** בנה את **Gljúfrasteinn** עם אשתו **Auður Sveinsdóttir** ב-**1945** ומעולם לא באמת עזב — זה היה הבית שלו עד מותו ב-**1998**, והיום זה מוזיאון ש**מכונת הכתיבה שלו עדיין מונחת בו על השולחן**.","b32c7c2d":"**תמונות המזבח של Kjarval, פרק ראשון:** ב-**1914** הוא צייר אחת לכנסיית **Bakkagerði** במזרח — ישו דורש מעל **Álfaborg**, סלע בני האלפים, ו-**Dyrfjöll** ברקע. הבישוף סירב לברך אותה — **יותר מדי בני אלפים, לא מספיק ישו**. היא תלויה שם עד היום, **בלי שהוקדשה מעולם** — ובגדול.","75cdf367":"**פרק שני:** תמונת המזבח השנייה שלו (*יוחנן המטביל, ישו לרגליו*) נפסלה על הסף בתור **\"גסה ומכוערת\"** — ואז **Halldór קנה את הפסולה ונתן לה קיר בבית הזה.** איש אחד, שתי תמונות מזבח, **אפס בישופים משוכנעים** — והצייר, הוויקינג של המבשל והסופר, שלושת שמות הכיס של הבוקר, כולם נקשרים כאן, בעמק האחד הזה.","bb9a5fdd":"הבית של המשורר: בית מגורים מ-1945, מוזיאון היום, ומכונת הכתיבה עדיין על השולחן","97b51e03":"אשתו, שבנתה איתו את הבית","a067a9fe":"חתן פרס הנובל היחיד של איסלנד, 1955","98b12d2a":"הצייר שתמונת המזבח הפסולה שלו תלויה בפנים","da3f1c33":"הכנסייה בפיורד המזרחי שעדיין מחזיקה את תמונת המזבח עם בני האלפים שלו מ-1914","69728231":"סלע בני האלפים שממנו ישו דורש באותו ציור","ca8f05a5":"ההרים שמאחורי הדמות","2aaf455f":"🚢 ההתפשטות הנורדית (793–1066 לספירה)","6dd800f8":"מתקרבים ל-Þingvellir.","7401ae6d":"**חברתי** — תחרות בין גברים צעירים ושאפתנים (ריבוי נשים, ירושה); האוכלוסייה גדלה מעבר למה שהאדמה יכלה להחזיק.","0d31ca86":"**כלכלי** — כסף, משי, תבלינים, ו**סחר עבדים** רווחי.","53be319f":"**פוליטי** — תגובה להתפשטות הנוצרית; מלחמה הביאה מעמד ואדמות חדשות.","84516bef":"**🌊 נתיבי ההתפשטות**","f8395a6a":"**🗺️ דפוסים**","b139f268":"**מצפון → לדרום:** פרוות, ענבר, עבדים, עצים ושנהב של סוס-ים — נשדדו ונסחרו ממנזרים, מעיירות נהר ומערי חוף מ**אירלנד ועד מרוקו** (כן, מרוקו — **פשיטת Nekor, בערך 859**).","d43edd1b":"**מדרום → לצפון:** **כסף** (דירהמים אסלאמיים), **משי**, תבלינים, נשק ומוצרי מותרות.","45a917ad":"**טווח:** רשתות ים ונהרות שחיברו את הארקטי לים התיכון — **יותר מ-6,000 מייל**, מבגדד עד אירלנד.","66af60ee":"**🌏 מה הם השיגו**","0c23b9d6":"רשת מסחר מ**הוולגה ועד Vínland**: כסף אסלאמי בסקנדינביה, ביזנטיון דרך הדנייפר — וההוכחה הקשה היחידה במערב, **L'Anse aux Meadows** שבניופאונדלנד (נחפרה ב-**1960**, אונסק\"ו **1978**), בערך 500 שנה לפני קולומבוס.","7753de04":"המורשת: החוק והשפה האנגליים, הסאגות, הפרלמנט העתיק בעולם (**Alþingi, 930**), ולידתן של **נורמנדי** ושל **רוס של קייב**.","0bdd8622":"**⏳ איך זה נגמר (1066)**","911ca0fe":"**קרב Stamford Bridge** — התבוסה של Harald Hardrada סוגרת את עידן הוויקינגים.","fc00b3eb":"למה: התגבשות פוליטית, התנצרות, הגנות חזקות יותר, התקררות האקלים ומעבר למסחר חוקי.","f47b8302":"**🗝️ תאריכי מפתח**","2168c5d9":"המתיישב הראשון של איסלנד; ההתיישבות מתחילה ב-870","40985d36":"האיש שהתיישב בגרינלנד ב-985","59c4aafe":"הגיע ל-Vínland בצפון אמריקה בסביבות שנת 1000","3141aa9b":"Harald Hardrada, שהתבוסה שלו ב-Stamford Bridge ב-1066 סגרה את עידן הוויקינגים","1e88e728":"מייסד שושלת רוריק ברוס'; הגיע לנובגורוד ב-862","a2c216fa":"כבש את קייב ב-882 והפך אותה לבירתו, וכך ייסד את רוס של קייב","3bae9e1a":"עיירת המסחר הדנית בנתיב הדרומי, בערך מ-804","8995257d":"השם הנורדי העתיק לקייב","824ff90c":"העיר הגדולה, כך הם קראו לקונסטנטינופול","ce5ffb4e":"ארץ היין, כך הם קראו לצפון אמריקה","b86e7143":"🏘️ Landnám","5cc5fb67":"חוצים את תקופת ההתיישבות.","241bd78a":"רוב המדינות נבנות במשך מאות שנים בידי צבאות. איסלנד נבנתה ב**שני דורות**, בידי חקלאים עם מחברות.","a6d3907d":"אבות מייסדים? יש לנו 400. נתנו שם לכולם. הם עדיין רשומים בספר.","f4545119":"חלופה למזג אוויר גרוע (אם הנוף לא נראה): \"ממילא אין כאן על מה להצביע — כל הסיפור הוא שארבע מאות מתיישבים מילאו את כל האי הזה תוך שישים שנה, ואנחנו עדיין יודעים את כל השמות שלהם, עם ערפל או בלי.\"","8636559c":"ה-**Landnám** (\"תפיסת הארץ\") הוא **חלון של כ-60 שנה** שבו יותר מ-9,000 מתיישבים נורדים, קלטים ואחרים תפסו כל מפרץ וכל עמק באי שאפשר לחיות בהם. (**874 הוא התאריך המסורתי**; Ari החכם מצביע יותר לכיוון **870**, ושכבת אפר שפרוסה על פני כל המדינה — ה-**tephra של 871 ± 2** — מחתימה את כל העסק בחותמת זמן כמעט לשנייה.)","506184af":"המקור הקנוני הוא **Landnámabók** (*ספר ההתיישבות*) — **400 מתיישבים** ברשימה שמית, עם החוות, הריבים ועיירות המוצא שלהם, בפירוט שאין לו מתחרים באף מדינה אחרת מעידן הוויקינגים.","029e10ca":"הטריק: באיסלנד **לא היו מקומיים להילחם בהם** — רק קומץ נזירים אירים (ה-**Papar**), שהסתלקו ברגע שהופיעו ספינות הדרקון.","0235b448":"עד שנת **930** האוכלוסייה (והריבים) גדלו מספיק כדי שראשי הקהילות ייפגשו ב-**Þingvellir** ויקימו את ה-**Alþingi**, הפרלמנט העתיק בעולם שעדיין פועל.","e2dff84e":"תפיסת הארץ, שישים השנים שבהן המתיישבים מילאו את האי","beec510a":"ספר ההתיישבות, שנוקב בשמותיהם של 400 מהם","e8939482":"הנזירים האירים שהסתלקו כשהופיעו ספינות הדרקון","a39ad432":"הפרלמנט הלאומי שהוקם ב-Þingvellir ב-930","1f6bb4e6":"Þingvellir","19fdd937":"⚖️ ה-Alþingi","60f89d14":"ב-Þingvellir — עמק הבקע.","68dab6ec":"בלי ארמון מלכותי. בלי עמודי שיש. רק סלע, קיר צוק, והפרלמנט הלאומי הראשון בעולם שהתקיים תחת כיפת השמיים.","c6449879":"בריטניה קוראת לעצמה בית הפרלמנט. באיסלנד הפעילו אחד **300 שנה לפני המגנה כרטה** — בתוך חור באדמה.","f2b5e342":"חלופה למזג אוויר גרוע (אם הבקע לא נראה): \"אם הערפל סגר על הבקע, זה דווקא מושלם — הוויקינגים בחרו במקום הזה בגלל הצוק שנשא את החוק המדובר, אז היום אתם מקבלים את הפרלמנט באוזניים, לא בעיניים.\"","61262941":"בשנת **930 לספירה** התכנסו ראשי הקהילות של איסלנד ב-**Þingvellir** וייסדו את ה-**Alþingi** — האספה הלאומית. הם בחרו דווקא במקום הזה כי קיר הצוק של ה-**Lögberg** (\"סלע החוק\") **נשא את החוק המדובר** על פני כל העמק.","65ffeb43":"במשך שבועיים בכל קיץ המדינה **נסגרה** וכולם הגיעו לכאן: חוקקו חוקים, סידרו שידוכים, שפטו רוצחים ושתו בירה.","4b0735e0":"ה-**Lögsögumaður** (דובר החוק), שנבחר ל**כהונה של שלוש שנים**, היה חייב לדקלם **שליש מכל קובץ החוקים בעל פה בכל שנה** — שלוש שנים כדי להעביר את הכול. מספיק לפספס סעיף אחד וכבר אפשר לשנות פסק דין.","c71441d3":"ולא היה **שום מלך** — בערך **36 goðar** (ראשי-כוהנים) ניהלו את כל העניין בהסכמה. חוק אחד, עם אחד, אפס כתרים.","c337c158":"הוא התכנס כאן בכל קיץ עד **1798**, ישב עוד שני קיצים ב-Reykjavík, ואז **בוטל כליל בצו מלכותי ב-6 ביוני 1800.** הוא הוקם מחדש ב-**8 במרץ 1843**, והתכנס שוב ב-**1 ביולי 1845** — ב-Reykjavík, בתוך בניין בית ספר. אז לא אלף שנים רצופות. אלף שנים עם **חור של 43 שנה** שדנמרק חפרה שם.","f724ea83":"וזאת בדיוק הסיבה שב-**17 ביוני 1944** הוכרזה כאן **הרפובליקה של איסלנד** המודרנית, ולא בבירה — על הקרקע שבה האומה התכנסה בפעם הראשונה, בגשם, מול עשרות אלפי אנשים. הם בחרו את הקרקע הזאת בקפידה כבר מלכתחילה: אפשר להגיע אליה מהצפון, מהדרום ומהמערב בתוך כ**שבעה עשר ימי מסע**, יש בה במה טבעית של צוקים ורצפה מישורית, וזו הייתה **אדמת ציבור שהוחרמה אחרי שבעליה הוצא אל מחוץ לחוק בגלל רצח.** פרקטי, דרמטי, ובאופן מודגש ניטרלי.","2c0e9cee":"האספה הלאומית שנוסדה כאן ב-930","5164c629":"סלע החוק, קיר הצוק שנשא את החוק המדובר על פני העמק","d1c1b35c":"דובר החוק, שדקלם בעל פה שליש מכל קובץ החוקים בכל שנה","7d24eea9":"ראשי-הכוהנים, בערך 36 במספר, שניהלו את זה בהסכמה","925f31aa":"🌍 הגיאולוגיה של Þingvellir","5ac99478":"רוב הגבולות בין הלוחות הטקטוניים מסתתרים מתחת ל-2 ק\"מ של אוקיינוס. כאן אתם יכולים **להיכנס ברגל אל תוך הפער שכדור הארץ קורע** — וגם לשתות ממנו.","466247b1":"שתי יבשות שנמשכות אחת מהשנייה. מי השתייה הנקיים ביותר בעולם זורמים דרך הפער. איסלנד הופכת אסון טקטוני לשתייה מרעננת.","a6ac09c9":"חלופה למזג אוויר גרוע (אם הבקע לא נראה): \"גם אם אתם לא רואים את הפער בין שתי היבשות במזג אוויר כזה, אתם עדיין עומדים בתוכו — והמים שנוטפים עליכם עזבו קרחון עוד לפני שהסבים והסבתות שלכם נולדו.\"","2c593b70":"תשכחו מגרסת הגלויה שבה אתם \"נוגעים בשתי יבשות בבת אחת\". **Þingvellir** יושבת על **רכס האמצע-אטלנטי**, ומה שאתם עומדים בתוכו הוא **גרבן ברוחב שבעה קילומטרים** — רצועת קרקעית עמק **ששוקעת בין שני קירות העתק** בזמן שהלוחות נמשכים זה מזה בערך **2 ס\"מ בשנה**. הלוחות בכלל לא נוגעים כאן; העמק **הוא** הפער ביניהם.","ef665b3b":"לסדקים יש שמות — **Almannagjá**, הגדול שאתם הולכים דרכו, הוא **הקצה הקרוע בצד הצפון-אמריקאי**; התאום שלו, **Heiðargjá**, מסמן את הצד הרחוק של הבקע. הרצפה שביניהם לא שייכת **לאף אחת מהיבשות** — היא התפר, והוא עדיין נקרע. את הפער ממלא **Þingvallavatn**, האגם הטבעי הגדול ביותר באיסלנד.","7c94fd63":"בריכות צלולות כמו **Silfra** הן מי הפשרה שעזבו את קרחון **Langjökull** לפני **30–100 שנה**, וסוננו מתחת לאדמה דרך לבה נקבובית — **אפשר לשתות אותם מכף היד**, והראות מתחת למים מגיעה עד **120 מ'**.","0c28d04f":"🎬 **על המסך:** קניון Almannagjá הוא המעבר אל **השער העקוב מדם** ב-*Game of Thrones* (השער נוסף דיגיטלית מעל שביל Öxarárfoss), והפארק שימש כממלכה מעולם אחר ב-***Thor: The Dark World*** (2013).","9b6e5b76":"זה לא זוחל בצורה חלקה — זה ננעל, נמתח, ואז משחרר. הפעימה הגדולה האחרונה הגיעה ב**אביב 1789**, הורידה את קרקעית העמק בערך **2.5 מ' בתוך כעשרה ימים** והציפה את השבילים סביב מתחם האספה הישן.","effad198":"המישור הוא **Þingvallahraun**, שדה לבת מגן **בן 9,000 שנה** שזרם לכאן מ-**Skjaldbreiður**. מאז הרצפה שקעה **יותר מ-40 מ'** והבקע נפתח בערך ב-**70 מ'**.","1ee6d12a":"מאז שנת **930** מתחם האספה עצמו ירד בערך **3–4 מ'** — הפרלמנט של ימי הביניים התכנס גבוה בצורה מורגשת מהמישור שאתם עומדים עליו.","55d2a5db":"**Þingvallavatn** הוא לא רק הגדול ביותר: בערך **84 קמ\"ר**, עומק של עד **114 מ'**, והקרקעית שלו נמצאת **מתחת לפני הים** בגלל הבקיעה. כמעט **90%** מהמים שלו לא מגיעים בנהרות אלא כ**מי מעיין קרים בטמפרטורה של 3–4°C**, מי הפשרה של **Langjökull** שסוננו במשך שנים דרך לבה נקבובית — וזאת בדיוק הסיבה ש-**Silfra** צלולה עד כדי אבסורד.","f5c2a725":"לאגם הזה הגיע דג אחד, סלמון ארקטי, אחרי שהקרח נסוג, והוא התפצל ל**ארבע צורות נפרדות בתוך כ-10,000 שנה** — אחד אוכל חלזונות, אחד ננסי, אחד ניזון מפלנקטון ואחד אוכל דגים. (אבולוציה שמסתעפת במקום, כשאין שום דבר שמפריד ביניהם חוץ מהתיאבון.)","db2b139f":"אם תלכו לאורך ה-**Öxará** מעבר ל-**Öxarárfoss**, תגיעו לבריכה ירוקה ודוממת בשם **Drekkingarhylur**, בריכת ההטבעה. אחרי הרפורמציה אימצה איסלנד קוד מוסר נוקשה, **Stóridómur**, ב-**1564**, ו-Þingvellir שימשה גם כמקום הוצאה להורג — גברים **נערפו, נתלו או נשרפו**, ונשים שהורשעו ב**ניאוף, גילוי עריות, עדות שקר או רצח תינוקות** **הוטבעו כאן**. פרוטוקולי בתי המשפט מצביעים על **לפחות שמונה עשרה נשים שנהרגו בבריכה הזאת בין 1618 בערך ל-1749**, ולוח זיכרון נוקב היום בשמותיהן.","c1ed5da9":"עוד כמה מספרים על האגם: העומק הממוצע שלו **34 מטר**, הוא יושב בערך **100.5 מטר מעל פני הים**, ואגן הניקוז שמזין אותו מגיע לכ-**1,300 קילומטר רבוע** — שמתוכם האגם עצמו הוא רק בערך **שישה אחוזים.** כל השאר זה צנרת שאתם לא רואים.","6f8634bd":"בערך **תשע עשיריות מכל מה שנכנס לאגם הזה מגיע מלמטה**, ומחלחל כלפי מעלה דרך לבה נקבובית. רק כ**עשירית** נכנסת כמים עיליים שאפשר לראות, והנהר הפתוח העיקרי שעושה את העבודה הזאת הוא ה-**Öxará** — זה שיורד מעל הקיר ב-Þingvellir. המים מתחילים כשלג על **Langjökull** ומבלים **שלושים עד מאה שנה** מתחת לאדמה לפני שהם עולים כאן לפני השטח. (המים שמולכם ירדו לפני שחלק מכם בכלל נולדו.)","5feccad1":"לארבעת הדגים יש שמות ששווה להכיר: **kuðungableikja**, זה שאוכל חלזונות, **dvergbleikja**, הננסי, **murta**, הקטן של המים הפתוחים, ו-**sílableikja**, אוכל הדגים. **שניים ניזונים מהקרקעית. שניים ניזונים במים הפתוחים.** אותו אגם, ארבע עבודות שונות לגמרי — והם **כולם מין אחד**, *Salvelinus alpinus*. הם יכולים להזדווג ביניהם ולהוליד צאצאים פוריים. הם פשוט מסרבים לרוב.","35e05775":"**שלושה מתוך הארבעה נבדלים גנטית זה מזה.** הרביעי, sílableikja, יוצא מבולבל גנטית — חלק מהפרטים נקראים כ-murta, אחרים ככלאיים בין sílableikja ל-kuðungableikja. ההערכה של Vísindavefurinn היא שאולי מדובר ב**ספיציאציה סימפטרית**, אוכלוסייה אחת שמתפצלת בלי שום מחסום פיזי בין החצאים, ושעוד **10,000 שנה** עשויות לייצר מינים נפרדים ממש. **האבולוציה עוד לא סיימה לסדר כאן.**","23a6dcd0":"האי הזה שם באגם הוא **Sandey**, **חרוט טוף** ש-**Hengill** בנה לפני כ-**1,900 שנה** — אותה התפרצות שהניחה את **Nesjahraun** בקצה הצפוני — כשהאפר שלה נישא בעיקר מזרחה מעל **Lyngdalsheiði**. התפרצות קרתה באמצע אגם ובנתה לעצמה מזה אי.","48813431":"עמק הבקע שאתם עומדים בתוכו, ששוקע בין שני הלוחות","9b95bd70":"הסדק הגדול שאתם הולכים דרכו; הקיר המערבי שלו הוא הקצה של הלוח הצפון-אמריקאי","e117d9c5":"ההעתק שמסמן את הצד הרחוק של הבקע","6861e56a":"הבריכה הצלולה שאפשר לשתות ממנה, ראות של עד 120 מ'","938174ce":"הקרחון שהמים האלה עזבו לפני 30 עד 100 שנה","0d1784d4":"האגם הטבעי הגדול ביותר באיסלנד, שממלא את רצפת הבקע","0291cdcf":"Þingvellir → עמק Haukadalur","9441bf1b":"🕳️ אנשי המערה","60d7b7ba":"עוברים ליד Laugarvatnshellir.","0b043379":"לאירופה של המאה העשרים היו ג'אז, מכוניות ורדיו. הייתה לה גם **משפחה שגידלה ילדים במערה**, כי זה מה שהיה.","5ba5d70a":"האגדה מספרת שרועה צאן כאן **נגרר שוב ושוב החוצה מהמערה בידי ידיים בלתי נראות** — ממש לפני סופת שלגים שהייתה הורגת אותו בפנים. באיסלנד אפילו העם הנסתר מוציא התרעות מזג אוויר משלו.","220b92f7":"חלופה למזג אוויר גרוע (אם המערה לא נראית): \"אם אתם לא מצליחים לאתר את המערה בתוך העכירות, זה דווקא מתאים — המשפחה האחרונה שגרה בה גידלה שלושה ילדים במזג אוויר בדיוק כזה, עם דלת כניסה ולא הרבה מעבר לזה.\"","9c5a0778":"**Laugarvatnshellir** הוא זוג מערות מעשה ידי אדם, שנחצבו בטוף וולקני רך על רמת הבור **Lyngdalsheiði**, מעל **Laugarvatn**.","b65b45da":"הראשונים שנכנסו, ב-**1910**: הנגר **Indriði Guðmundsson** ו-**Guðrún Kolbeinsdóttir**, שהפעילו **אוהל של קפה, לחם ועוגות** לנוסעים שעברו במעגל הזהב.","00d0ac36":"ואז **1918–1922**: **Jón Þorvarðsson** ו-**Vigdís Helgadóttir** גידלו **שלושה ילדים** בתוך הסלע. כשסופת שלגים חסמה את המיילדת, Jón **יילד בעצמו את בתו Ragnheiður** — אבא המערה של המאה.","093a413b":"וזה גם לא ימי הביניים: זה היה **באותו עשור של הפורד מודל T**. המקום נפתח מחדש למבקרים ב-**2017** — הדלת המקורית חזרה למקומה, כולל קנקן הקפה.","d4f8713f":"זוג המערות מעשה ידי אדם שמשפחות באמת גרו בהן עד 1922","d7ca6659":"המקום בקצה הרחוק של הרמה הזאת; המערות נקראות על שמו","fa1925ce":"הנגר שנכנס לגור שם ראשון, ב-1910","ab8f2090":"הדיירת השנייה של 1910; יחד הם הפעילו אוהל של קפה ועוגות לנוסעים","991c5e7f":"האב שיילד כאן את בתו בעצמו כשסופת שלגים חסמה את המיילדת","4cb2068b":"האם שגידלה שלושה ילדים בתוך הסלע, מ-1918 עד 1922","7718f90e":"הבת שנולדה במערה","996bfccc":"הרמה שבה נחצבו המערות","df40b856":"⚖️ Kristnitaka","7a14f5a2":"תסתכלו קדימה — Þingvellir, המקום שבו התקבלה ההחלטה.","d97e4a56":"רוב הדתות הלאומיות נכפות בידי מלכים או נקבעות בידי צבאות. זו של איסלנד הוכרעה בידי **אדם אחד שנשכב לישון**.","d74db88a":"בשקט, ביחד, ואחרי לילה של שינה ממש טובה. ככה איסלנד הפכה לנוצרית. לרוב המדינות בכלל לא נתנו את האפשרות.","d973a1e4":"חלופה למזג אוויר גרוע (אם Þingvellir שלפנינו לא נראית): \"ממילא אין מה לראות מקדימה — כל הדרמה הייתה אדם אחד ששכב מתחת לגלימה יום ולילה, מה שבמזג אוויר כזה נשמע כמו האופציה ההגיונית.\"","477fd887":"עד **999** המדינה הייתה מפולגת — מחוזות נוצריים מול מעוזים פגאניים — ומלך נורווגיה **Ólafur Tryggvason** לחץ חזק: הוא קיבל בברכה סוחרים נוצרים לנמלים שלו, חסם את הפגאנים, ו**החזיק בני ערובה איסלנדים** כקלף מיקוח. או שתתנצרו, או שתאבדו את נתיב הסחר שאי אפשר לחיות בלעדיו.","3277ef89":"השכנוע לא הלך טוב: כומר סקסוני אחד, **Þangbrandur**, לפי הטענה **יצא לדו-קרבות והרג משוררים** שלעגו לדרשות שלו. לא בדיוק מסע קסם וחיוכים.","74af91f5":"עד **שנת 1000 לספירה** (המקורות מתנדנדים בין 999 ל-1000) ה-**Alþingi** עמד מול שתי דתות, שני קובצי חוקים ומלחמת אזרחים אחת שמתקרבת — אז שני הצדדים מסרו את ההכרעה לאיש אחד: **Þorgeir Ljósvetningagoði**, דובר החוק ה*פגאני*.","a20108ac":"הוא שכב מתחת לגלימה שלו **יום שלם ולילה שלם**, ואז פסק: **חוק אחד, עם אחד, אמונה אחת — נצרות** — כדי שהחבר העצמאי הצעיר לא יתפצל לשניים. קורבנות בצנעה, בשר סוסים והפקרת תינוקות הותרו בשקט בהתחלה, ואחר כך בוטלו. אוכל זה אוכל.","f5551fdf":"דובר החוק הפגאני ששכב מתחת לגלימה שלו יום ולילה, ואז בחר בנצרות","77b34d60":"הכומר הסקסוני שיצא לדו-קרבות עם המשוררים שלעגו לדרשות שלו","928d426a":"מלך נורווגיה, שלחץ על איסלנד עם חסימת נמלים ובני ערובה","b33c859a":"🌋 Hekla","cfcaf0da":"תסתכלו ימינה, בשעה 1 — Hekla, שישים קילומטר מכאן על קו האופק. רק בימים בהירים.","5252f447":"רוב הרי הגעש מקבלים ערך בוויקיפדיה. Hekla קיבלה ערך **תיאולוגי** — כזה ששימש להפחיד את אירופה של ימי הביניים במשך 800 שנה.","8e2bcfc1":"ברוכים הבאים לשער הגיהינום. הוא נותן לכם בקושי **שעה וחצי התראה** כדי לשלוח את הגלויות.","7918adae":"חלופה למזג אוויר גרוע (אם Hekla לא נראית): \"ממילא כמעט אף פעם לא זוכים לראות את Hekla, אז אם העננים מסתירים אותה היום, פשוט תדעו ששער הגיהינום של ימי הביניים נמצא שם בשעה 1, מזעיף פנים מאחורי מזג האוויר.\"","aaacfd65":"**Hekla** — **1,491 מ'**, התפרצה **יותר מ-20 פעמים מאז הוויקינגים**; הפיצוץ של **1104** (**VEI 5**) הפיל בערך **2 קמ\"ק של tephra על פני 55,000 קמ\"ר**, אחת הגדולות ברישומים של איסלנד, וזו שהתחילה את האגדה.","7004bfca":"כשהשמועה על 1104 הגיעה לאירופה, **נזירים ציסטרקיאנים** רצו איתה קדימה — כבר ב-**1180** כתב הרברט מקלרוו שלעומת Hekla, האתנה הוא \"תנור קטן\".","c2b9cb1f":"לאורך המאות ה-12 וה-13 הכריזה הכנסייה על Hekla כ**פתח הגיהינום ממש** ובית הכלא של **יהודה איש קריות**.","04a8f738":"ההתפרצות האחרונה שלה הייתה ב**פברואר 2000** — ו-Hekla כל כך שקטה באופן מצמרר לפני כן, שהסייסמוגרפים קלטו את ההכנות שלה רק בערך **80 דקות** לפני שהיא התפוצצה.","83c2ad0d":"ביום ממש ממש בהיר, אותו קו ראייה עצמו מסדר בשורה **עוד שלושה הרי געש מכוסי קרח** לכיוון החוף: **Tindfjallajökull**, אחר כך **Eyjafjallajökull** — המפורסם מענן האפר של 2010 — ואז **Mýrdalsjökull** מאחוריו.","53f128f2":"היא הרבה יותר מבוגרת ממה שקורות החיים שלה מרמזים. הסיפור של ה-Hekla שהיינו מזהים היום מתחיל **קצת יותר מ-7,000 שנה אחורה** — היא כבר הייתה בעסק הרבה לפני שהיה כאן מישהו שירשום. **1104** הייתה **ההתפרצות הראשונה שלה אחרי ההתיישבות באיסלנד** — והיא עדיין **ההתפרצות הנפיצה הגדולה ביותר שלה בזמן ההיסטורי.** (ההתפרצות הנפיצה הגדולה יותר ברישומים ההיסטוריים של איסלנד שייכת למתחרה: **Öræfajökull ב-1362.**) לפני כן היא הייתה שקטה בערך **שלוש מאות שנה**, כלומר לאף אחד מהחיים אז לא היה מושג קלוש במה היא מסוגלת.","54de403d":"האפר של 1104 הלך צפונה, ומחוזות החקלאות **Þjórsárdalur** ו-**Hrunamannahreppur** **ננטשו** בגללו. איסלנד קיבלה מההתפרצות הזאת אלף שנה של יחסי ציבור באירופה, ו**לא כתבה מזה שום דבר** — האנשים שבאמת חיו מתחת היו עסוקים בדברים אחרים, כמו לפנות שני מחוזות.","e3475800":"לסיפור על יהודה יש תאריך ויש מסמך. **תוך עשר עד עשרים שנה מ-1104** כבר טען **שיר אנגלי** ש**יהודה** — הבוגד הראשי בכבודו ובעצמו — כלוא בתוך Hekla, ואנשי הכמורה באירופה ממש שמחו לקבל דיווחים על התפרצויות, כי מבחינתם התפרצות **הוכיחה שהגיהינום קיים.** התמונה שקיבעה את זה הייתה חיתוך עץ בספר ההיסטוריה של עמי הצפון מאת איש הכנסייה השוודי **Olaus Magnus (1490–1557)**, שיצא לאור ב**ונציה ב-1555**, ובו Hekla עם מערכת מנהרות שיורדת מתוך ההר. **הווזוב והאתנה מעולם לא זכו לאותו מוניטין** — ו-Vísindavefur מציע את ההסבר היבש ביותר שאפשר. הם היו **קרובים מדי לציוויליזציה.** הר געש שנמצא בבטחה מעבר לקצה של אירופה עשה דלת כניסה הרבה יותר משכנעת.","0cd1f0da":"ההתפרצות הארוכה ביותר שלה התחילה ב-**5 באפריל 1766** ונמשכה עם הפסקות עד **מאי 1768** — **קצת יותר משנתיים**, כולל **הפסקה של שישה חודשים** באמצע, שבטח הרגישה לכולם כמו הסוף.","add2993b":"הר הגעש בגובה 1,491 מ' בשעה 1, שאירופה של ימי הביניים קראה לו שער הגיהינום","c83ca667":"אפר ורסיסים וולקניים; Hekla הפילה בערך 2 קמ\"ק מזה ב-1104","e07017c5":"הראשון משלושת הקרחונים שנראים ביום בהיר במיוחד","0403b687":"הר הגעש של ענן האפר מ-2010, השני בשורה","387c3243":"הקרחון השלישי בשורה, הרחוק ביותר לכיוון החוף","973d6ce2":"🛁 Laugarvatn ו-Apavatn","7810444a":"תסתכלו ימינה, בשעה 3 — האגם Laugarvatn.","2205fe0b":"רוב האומות התנצרו בקצה החרב. המתנצרים של איסלנד **בדקו קודם את טמפרטורת המים.**","0a8d97ec":"מדינות אחרות הוטבלו בנהרות קפואים. איסלנד הסתכלה על מזג האוויר ואמרה — לא, יש לנו אחד חמים.","9afc9870":"חלופה למזג אוויר גרוע (אם האגם לא נראה): \"אם הגשם הסתיר את Laugarvatn מימין, תדמיינו אגם כל כך חמים שהחוף שלו מעלה אדים בחורף — הוויקינגים הוטבלו בו בדיוק כדי שלא יצטרכו לעמוד במזג אוויר כזה.\"","67e4b110":"**Laugarvatn** (\"אגם הבריכה\", בערך 260 תושבים) יושב על **גוש Hreppar** — מעיינות גיאותרמיים בטמפרטורה של **35–40°C** מזינים את קרקעית האגם, ולכן אפילו בחורף חלקים מהחוף נשארים בחום של אמבטיה.","398f769f":"הרגע הגדול שלו הגיע בערך בשנת **1000 לספירה**: אחרי שהנצרות כבר עברה בהצבעה ב-Þingvellir, אנשי הצפון והדרום שזה עתה התנצרו רכבו לכאן כדי שיוכלו **להיטבל במעיין החם** במקום בנהר הקפוא. המעיין — שנקרא פעם **Reykjalaug** — שינה לכבוד האירוע את שמו ל-**Vígðalaug, \"הבריכה המקודשת.\"** (לאנשי המערב היה מעיין חם משלהם ב-Krosslaug. באיסלנד ניהלו טבילות לפי מיקוד.)","26f91edd":"האגם השכן **Apavatn** (\"אגם הביצה\") הוא המקום שבו קרתה \"הפוליטיקה הקרה\" — שם התרחש אחד המארבים המלוכלכים ביותר בהיסטוריה של איסלנד. תחזיקו את המחשבה: כל הסיפור העקוב מדם מגיע ממש אחרי הנהר הבא.","fe43a96b":"היום יש ב-Laugarvatn את המרחצאות הגיאותרמיים **Fontana** — אותו חום בדיוק שהמיר את הפגאנים, רק שעכשיו יש גם בר.","b91d7242":"אגם הבריכה מימין, חמים מספיק ליד החוף כדי להתרחץ בו באמצע החורף","67a73111":"אגם הביצה שלידו, שבו התרחש המארב של 1238","c1993131":"הבריכה המקודשת, המעיין החם שבו הם בחרו להיטבל","ada0abe0":"המרחצאות הגיאותרמיים שם היום: אותו חום, עכשיו גם עם בר","b78643d5":"💙 Brúará","5f983571":"חוצים את Brúará.","bcba6d65":"נהר שנקרא על שם גשר — ושאיבד את הגשר כי לכנסייה נמאס שהעניים ממשיכים להגיע.","7915d09d":"מדיניות הגבולות הזולה ביותר בהיסטוריה של איסלנד: להרוס את הגשר היחיד ולתת לנהר לעשות את השאר.","69ec9658":"חלופה למזג אוויר גרוע (אם הנהר לא נראה): \"אם אתם לא רואים את הנהר שאנחנו חוצים, אתם מפספסים מפל בכחול זוהר בשם Brúarfoss — תתייקו את זה תחת 'סיבות לחזור ביום בהיר יותר'.\"","feaa099f":"**Brúará** (\"נהר הגשר\") הוא נהר צלול שניזון ממעיינות ומזין את ה-Hvítá; הפנינה שלו היא המפל בכחול הזוהר **Brúarfoss**. במשך מאות שנים **קשת אבן** טבעית כאן הייתה המעבר היחיד במרחק מיילים.","becbd9e9":"בשנת הרעב **1602**, המנהל של **Skálholt** — אחוזת הכנסייה הגדולה שנבקר בה אחר הצהריים — ובידיעתה של אשת הבישוף, **Helga Jónsdóttir**, דאג ש**הקשת תיהרס בכוונה**, כדי למנוע מאנשים עקורים ורעבים לחצות אל האדמות הפוריות של האחוזה. צדקה בסגנון Skálholt: להרוס את הגשר כדי שהרעבים לא יוכלו לעבור עליו.","a7ef9104":"לנהר הזה היה עבר: עוד ב-**1433** הבישוף המודח **Jón Gerreksson** **הוטבע בו בתוך שק** כהוצאה להורג. לא נהר של מזל בשביל מי שחייב כסף לבישוף. תחזיקו את שני הסיפורים ביד — אנחנו מגיעים לאחוזה עצמה אחר הצהריים.","92d08c6c":"נהר הגשר, הנהר הצלול שניזון ממעיינות ושאנחנו חוצים עכשיו","6237e3ad":"המפל שלו בכחול הזוהר","eff7587e":"אשת הבישוף שידעה שקשת האבן נהרסת ב-1602","84e49abd":"הבישוף המודח שהוטבע בנהר הזה בתוך שק ב-1433","dce1b4b2":"הנהר הקרחוני שהנהר הזה מזין","ab7c4ce6":"האחוזה שהמנהל שלה דאג שהגשר ייהרס — אנחנו מבקרים בה אחר הצהריים","836ab5e7":"⚖️ עידן ה-Sturlungar","72308a5f":"*הפרק מהמאה ה-13 שרוב הסיורים מדלגים עליו.*","c098b3af":"איסלנד לא איבדה את העצמאות שלה לצבא. היא **איבדה אותה לעצמה**.","16b83d34":"הפרלמנט הכי עתיק בעולם נהרג בדיוק בידי אותן משפחות שהוא הוקם כדי לרסן.","5fc1a979":"חלופת מזג אוויר (אם הנוף לא נראה): ״אין פה על מה להצביע — זה סיפור, לא נוף: רפובליקה בת שלוש מאות שנה שקרעה את עצמה לגזרים בשקט, והכי מתאים לספר אותה כשהחלונות מאודים והאווירה כבדה בדיוק כמו שצריך.״","adf12814":"**Sturlungaöld** נמשכה בערך בין **1220–1262** — המלחמה הפנימית הארוכה והמכוערת ביותר בתולדות איסלנד.","00092323":"הכוח התרכז אצל כמה חמולות גדולות, ובעיקר אצל ה־**Sturlungar** (כן, המשפחה של כותב הסאגות **Snorri Sturluson**). סכסוכים הפסיקו להגיע ל־Althing והתחילו להגיע ל**חרבות, שריפות והתנקשויות**.","fe32a190":"**באביב 1238, ב־Apavatn** — האגם שרק עכשיו עברנו לידו — **Sturla Sighvatsson** ארב ליריבו **Gizur Þorvaldsson** ממשפחת Haukdælir ואילץ אותו **להישבע על כתבי הקודש** שיוותר על השלטון ויפליג לנורווגיה. ל־Gizur היו האצבעות משוכלות מאחורי הגב.","d1110dbd":"חמישה חודשים אחר כך הגיע מועד הפירעון של השבועה ב־**Örlygsstaðir (21 באוגוסט 1238)** — Gizur חבר ל־**Kolbeinn ungi** והביא **בערך 1,700 איש מול בערך 1,000** אל **הקרב הגדול ביותר שנערך אי פעם על אדמת איסלנד**. ה־Sturlungar הצפוניים נמחקו בתוך אחר צהריים אחד; החנית המשפחתית העתיקה של Sturla, **Grásíða, לא הפסיקה להתעקם לו בידיים** בזמן שהקרב התהפך, ואומרים ש־Gizur הוא זה שהנחית את המכה הסופית.","62246b07":"Snorri עצמו — האיש שהעלה על הכתב את המיתולוגיה הנורדית — **נרצח במרתף של עצמו ב־Reykholt ב־23 בספטמבר 1241**, בפקודת מלך נורווגיה, בידי כנופיית פורעים בראשות **Gizur Þorvaldsson, החתן־לשעבר שלו**. המילים האחרונות שלו: ***״Eigi skal höggva!״*** — ״אל תכו!״ הם היכו.","e9f23cf5":"נקודת השפל: **שריפת Flugumýri (1253)** — מארב בחתונה, האולם הועלה באש עם המשפחה בפנים. (מקשרים את זה לא פעם ל״חתונה האדומה״ מ*משחקי הכס* — טענה פופולרית; ראו רשימת האימות.)","f56d4006":"עד **1262**, מותשים, ראשי החמולות חתמו על **הברית הישנה** ומסרו את המדינה למלך נורווגיה. הרפובליקה בת 300 השנה נגמרה.","d7754195":"תקופת ה־Sturlungar, המלחמה הפנימית הארוכה ביותר של איסלנד, בערך מ־1220 עד 1262","2a6f676b":"האיש שהעלה על הכתב את המיתולוגיה הנורדית, נרצח במרתף של עצמו ב־1241","844b1dac":"הקרב של 1238 שבו ה־Sturlungar הצפוניים נמחקו בתוך אחר צהריים אחד","b7aa2341":"מנהיג ה־Sturlungar שהפעיל את המארב ב־Apavatn","e0c4853a":"היריב שנשבע, הפר את השבועה, וניצח","03940654":"החנית המשפחתית העתיקה של Sturla, שלא הפסיקה להתעקם לו בידיים","ebef1eeb":"האגם שבו התרחש המארב, בערך חמש דקות אחורה בכביש","87122206":"האחוזה של Snorri, המקום שבו הוא נרצח","af330421":"מארב החתונה של 1253 שבו האולם הועלה באש עם המשפחה בפנים","526fc5a1":"⚖️ Haukadalur","172426ec":"בשדה הגיאותרמי של Haukadalur.","91da53a1":"עמק אחד, משפחה אחת: שושלת הבישוף הראשון, חדר הלימוד ששימר את הזיכרון של איסלנד — והרוזן שבחתימה אחת מסר את הרפובליקה.","a8159455":"הנצים של העמק הזה לימדו את איסלנד לקרוא, לכתוב ולהתפלל — ואז אחד מהם מכר את כל המדינה לנורווגיה. מורשות משפחתיות זה עניין מסובך.","75f3f8ff":"חלופת מזג אוויר (אם העמק לא נראה): ״אם האדים והערפל התמזגו לקיר לבן אחד, זה דווקא מתאים — המשפחה שניהלה את העמק הזה כיוונה את איסלנד במשך מאתיים שנה, בעיקר מתוך חדרים שגם לתוכם אי אפשר היה לראות.״","4b963ac3":"**Haukadalur** פירושו **״עמק הנצים״** — היום מכירים אותו בזכות האדים, אבל במשך מאתיים שנה זה היה **מושב של ראש חמולה**: חוות האם של ה־**Haukdælir**, אחת ממשפחות הכוח הגדולות של חבר העמים האיסלנדי.","23790921":"**Teitur Ísleifsson** — בנו של **Ísleifur Gissurarson, הבישוף הראשון של איסלנד** — התיישב בחווה הזאת והפך ל**אבי שושלת ה־Haukdælir**. הוא ניהל כאן בית ספר מפורסם במאה ה־11, ואחד התלמידים שהתגוררו בו, מגיל **שבע** בערך, היה **Ari fróði Þorgilsson** (״החכם״, בערך 1067–1148) — שכשגדל כתב את **Íslendingabók**, הסיבה היחידה שיש לאיסלנד בכלל תאריכים מוקדמים ודאיים. (כתר בית הספר ה*ראשון* שייך ל־**Skálholt**, קצת הלאה בכביש — נגיע לשם.)","254aabec":"המשפחה נשארה בצמרת במשך מאתיים שנה — בישופים, אנשי חוק, ולבסוף **Gizur Þorvaldsson**, מפר השבועה של Örlygsstaðir מהתחנה הקודמת: **Haukdæling**, שהפך ל**רוזן הראשון והיחיד של איסלנד ב־1258**, ארבע שנים לפני שהרפובליקה שהוא עזר לקבור נמסרה לנורווגיה.","4ab4e479":"בעמק נמצאים גם המעיינות החמים **Geysir** ו־**Strokkur** — הגייזר המקורי שנתן לעולם את המילה ״גייזר״ — על **גוש Hreppar**, שם מים בחום־על מגיעים אל פני השטח.","759dfc4d":"עמק הנצים, העמק המהביל שאנחנו נמצאים בו","26f90541":"בנו של הבישוף הראשון, אבי שושלת ה־Haukdælir, שניהל את בית הספר בחווה הזאת","72200e72":"״החכם״, הילד שלמד כאן וכשגדל כתב את ספר ההיסטוריה הראשון של איסלנד","213b8e60":"הספר שהוא כתב, הסיבה היחידה שיש לנו בכלל תאריכים מוקדמים ודאיים","fa4d16b4":"שושלת עמק הנצים: בישופים, מנהלי בתי ספר ורוזן אחד","d8a08ca5":"הבישוף הראשון של איסלנד, אביו של Teitur","87751d79":"ה־Haukdæling שהפר את השבועה, ניצח בקרב והפך לרוזן היחיד של איסלנד","ef7b6696":"Geysir","8a24712b":"⛲ Geysir","d33ed042":"בשדה הגיאותרמי — Strokkur ו־Geysir.","43b6a8dd":"כל גייזר אחר על פני כדור הארץ קרוי על שם **זה שכאן**. ילוסטון, ניו זילנד, צ׳ילה — כולם בני דודים גיאולוגיים של מעיין חם איסלנדי אחד.","d311999e":"איסלנד ייצאה את המילה ״גייזר״ עוד לפני שהיא ייצאה את הבקלה.","23609350":"חלופת מזג אוויר (אם ההתפרצות לא נראית): ״גם בערפל סמיך תשמעו את Strokkur מתפרץ ותרגישו את האדמה נדרכת רגע לפני — הגייזר שנתן את השם לכל האחרים לא צריך שתראו אותו כדי להעביר את המסר.״","059d760e":"ה־**Geysir** המקורי מתועד לראשונה ב־**1294**, כשרעידות אדמה שינו את צורת המעיינות בשדה — בשיאו הוא זרק מים לגובה **60–80 מ׳**. היום הוא **רדום** ברובו, אבל בן הדוד האמין שלו, **Strokkur** (״המחבצה״), יוצא **כל 6–10 דקות**, לגובה **15–20 מ׳** (מדי פעם 40).","eb32b061":"שימו לב איך ה**כיפה** מתנפחת רגע לפני היציאה: שכבה דקה של מים קרירים יותר מעל מים כמעט רותחים, והלחץ עולה עד שהוא פורץ החוצה.","7c06a49f":"השדה יושב על **גוש Hreppar** — מים מחלחלים למטה, פוגשים **סלע בחום של 200°C ומעלה**, הופכים בבת אחת לאדים ויורים בחזרה למעלה.","2b97a31e":"**Geysir עובד על רעידות אדמה.** הוא נולד בכתובים אחרי רעידות **1294**, והוא שואג בחזרה אחרי כל טלטלה גדולה בדרום — **1630**, **1896**, ולאחרונה **ביוני 2000** — ואז נרדם שוב בין לבין, לפעמים לעשרות שנים.","17a8964c":"האיסלנדים אף פעם לא ממש השלימו עם התנומות: פעם הם היו **מגרפים לתוכו סלעים וכבול** כדי להרגיז אותו, ומ־**1963 עד 1981** הטריק הרשמי היה **סבון** — מורידים את מתח הפנים והמים בחום־על גולשים ברתיחה. המדינה פשוט **שטפה לגייזר שלה את הראש עד שהופיע**. (מאז אנחנו נותנים לו לישון בכבוד.)","6139993c":"השם **Geysir** (מהמילה *geysa*, ״לפרוץ״) מופיע בכתב לראשונה ב־**1647** — וכשמדעני הנאורות התחילו להתעניין, המילה התפשטה ל**כל שפה על פני כדור הארץ**, הכול מהשדה האחד הזה.","a1947276":"בתקופות השיא שלו לקח לו **8 עד 10 שעות** להתמלא מחדש בין התפרצויות. ב־**1896** הוא חזר והתפרץ **כמה פעמים ביום**, ואז נרדם בערך ב־**1915**.","f2fd580b":"**ב־1935 נחצב תעלה** כדי להוריד את מפלס המים ולהפעיל אותו מחדש, וב־**1981 חצבו והעמיקו אותה שוב**.","d7e5cc95":"**Strokkur** הוא תרמודינמיקה נטו: **מטר אחד למטה המים הם 90–95°C**, ב־**עשרה מטרים 112°C**, ובתחתית **הפיר בעומק 23 מטר בערך 130°C** — והם נשארים נוזליים רק בגלל משקל המים שמעליהם. תורידו את המכסה והם הופכים לאדים בבת אחת.","787309bc":"מדידות של התפרצויות ב־**2000** הראו בין **270 ל־425 ליטר** מים בערך, או **300 עד 500 ליטר** אם סופרים גם את מה שיוצא כאדים.","794e56aa":"האמינות של **Strokkur** צעירה מרוב הקהל שלו. אומרים שההופעות שלו במאה התשע־עשרה **נמשכו שעה והגיעו עד 60 מטר** — ואז הוא השתתק לעשרות שנים. ב־**1963** התקבלה ההחלטה **לקדוח בערך 40 מטר לתוך ה־gosskál**, אגן ההתפרצות, ומאז הוא **פעיל בצורה יוצאת דופן**. המופע הטבעי הכי אמין במדינה הזאת הוא לא לגמרי טבעי.","eb8464ed":"עוד מספר אחד על הפיר: **עורק מים קרים נכנס בערך ב־13 מטר** עומק. זו חלק מהסיבה שהגובה, משך ההתפרצות והמרווח משתנים כל הזמן — ולמה אף אחד לא ייתן לכם לוח זמנים, אז תסתכלו על המים ולא על הטלפון.","4e50b714":"המעיין החם המקורי שנתן לכל שפה את המילה גייזר; היום רדום ברובו","291c5a4b":"המחבצה, בן הדוד האמין שלו שיוצא כל 6 עד 10 דקות","89027664":"Gullfoss","c87be82c":"💧 Hvítá ו־Gullfoss","08c71a89":"ב־Gullfoss.","c6db9212":"סיפור השימור האיסלנדי המפורסם בעולם — הפסידו בבית המשפט, ניצחו בסוף, בזכות אישה שמעולם לא הייתה לה זכות הצבעה.","a4037a17":"משקיע הגיע עם מהנדסים. בת של איכר הגיעה והפסידה בכל סיבוב משפטי — והמפלים עדיין כאן.","65fc02ca":"חלופת מזג אוויר (אם המפלים לא נראים): ״אם הרסס והערפל הסתירו את Gullfoss, סמכו על האוזניים — השאגה הזאת היא שלושים ושניים מטר של מי המסת קרחון, שבת של איכר אחת נלחמה בבתי המשפט כדי שימשיכו ליפול.״","0bca46d8":"**Gullfoss** (״מפלי הזהב״) מפיל את ה־**Hvítá** בשתי מדרגות, **32 מ׳** בסך הכול, לתוך קניון צר — והרסס מייצר קשתות בענן בעקביות כזאת שזה נראה מבוים.","7a8919fe":"ה־Hvítá הוא **מי המסת קרחון** מ־**Langjökull**, עמוס מספיק בסחף כדי לזהוב באור הקיץ.","b1de3fef":"ב־**1907** אנגלי אחד חכר את המפלים מהאיכר **Tómas Tómasson** בשביל **תחנת כוח הידרואלקטרית**. בתו, **Sigríður Tómasdóttir**, הוציאה את החסכונות שלה על עורך דין מ־Reykjavík — **Sveinn Björnsson**, לימים **הנשיא הראשון של איסלנד** — ונלחמה שנים כדי לבטל את החכירה. הפרטים המפורסמים על ״הליכה יחפה ל־Reykjavík״ ו״האיום לקפוץ״ הם **רומנטיזציה**; היא באמת **הפסידה בבית המשפט**, אבל החכירה **פקעה אחר כך כי היזמים הפסיקו לשלם את דמי השכירות**.","202c435f":"Gullfoss שרד, הפך ל**שמורת טבע ב־1979**, ו־Sigríður — שמונצחת באנדרטה מעל המפלים — נקראת היום **הסביבתנית הראשונה של איסלנד**.","7c0391f4":"הערוץ שלמטה הוא באורך **2.5 ק״מ ובעומק 70 מ׳** בערך, והספיקה הממוצעת מעל השפה היא **109 מ״ק לשנייה**.","43c27aed":"ההצעה של האנגלי, בתחילת **1907**, הייתה **50,000 krónur** — ואיסלנד העבירה באותה שנה חוק שהגביל **בעלות זרה על מפלי מים**, ואחריו גורמים זרים השיגו זכויות שכירות בכל מקרה.","514c857d":"**Sigríður Tómasdóttir**, **1871 עד 1957**, הגיעה מהחווה **Brattholt** שמעל המפלים, ומה שהיא ניסתה שנים לבטל היו ההסכמים **שאבא שלה עצמו חתם עליהם**. פסק הדין ניתן נגד משפחת Brattholt.","43803a05":"מה שבאמת הציל את המקום היה משעמם יותר מהאגדה: ב־**1928** תשלומי השכירות הפסיקו וההסכם פקע. הכרזת השמורה נחתמה ב־**9 במרץ 1979** ומשתרעת על **164.2 הקטאר**.","9bb5bd34":"עורך הדין שלה היה **Sveinn Björnsson**, שהמשיך והפך לנשיא הראשון של איסלנד, **1944 עד 1952**. (מסתבר שההפסד בתיק הזה עשה פלאים לקורות החיים שלו.)","3221c1c4":"🎬 **על המסך:** Gullfoss מופיע ב*ויקינגים* (בעונות המאוחרות) וב*אבודים בחלל* של נטפליקס — והוא ״ארגנטינה״ בפרק ״Zod״ של *סמולוויל* (2006), שבו בשוט האחרון כתוב *מפלי Iguazú* אבל זה Gullfoss לגמרי.","73c8fb5b":"מפלי הזהב, הנפילה הדו־מדרגתית בת 32 מ׳ שלפניכם","9b391fc7":"הנהר הקרחוני שנופל מעליהם","f158d981":"בת האיכר שנלחמה בסכר, ונקראת היום הסביבתנית הראשונה של איסלנד","0a040a17":"עורך הדין שלה מ־Reykjavík, לימים הנשיא הראשון של איסלנד","4847b7cc":"הקרחון שמי ההמסה שלו מזינים את ה־Hvítá","8c3e1325":"Gullfoss ← BSÍ","c01ffbe9":"⚡ Tungufljót","78bc9025":"חוצים את נהר Tungufljót.","83770ee5":"המפל הכי מצולם באיסלנד הוא Gullfoss. הכי שימושי הוא **היובל הזה שאתם חוצים עכשיו**, שעושה את העבודה האמיתית של להשאיר את האורות דולקים.","1a210bf2":"Gullfoss מקבל את התמונות. Tungufljót מקבל את חשבון החשמל משולם.","61ff553f":"חלופת מזג אוויר (אם הנהר לא נראה): ״אולי לא תראו את הנהר הקטן שאנחנו חוצים, אבל הוא הגיבור הלא־זוהר של הסיפור — מייצר חשמל בשקט בזמן ש־Gullfoss המפורסם רק עושה פוזות למצלמה.״","010125d4":"**Tungufljót** (״נהר הלשון״) מנקז את הרמות אל תוך ה־**Hvítá**, ומוצג הראווה שלו הוא **Faxi** (Vatnsleysufoss) — מפל רחב ונמוך, וילון של **בערך 7 מ׳** עם **סולם דגים לסלמון** בנוי בתוכו.","a2b3378e":"המים שלו מסובבים היום את **Brúárvirkjun**, תחנת כוח הידרואלקטרית קטנה של **Landsvirkjun** שסוכרת את הנהר בחלקו העליון — מתקן מודרני שנפתח בתחילת שנות ה־**2020**. זעיר בקנה מידה עולמי; גדול מספיק כדי להחזיק את הפיסה הזאת של הדרום על הרשת.","0ebb084d":"איסלנד רצה על **בערך 70% הידרו** ועוד גיאותרמי — רשת חשמל **מתחדשת בכ־99.9%**, אחת הנקיות בעולם. נהרות קטנים ושקטים כמו זה הם הרוב שמאחורי המספר הזה.","b2b8bab9":"נהר הלשון, הנהר השקט שאנחנו חוצים","967adab8":"Vatnsleysufoss, וילון המפל הרחב שלו בגובה 7 מ׳ עם סולם דגים לסלמון בנוי בתוכו","10899df9":"תחנת הכוח ההידרואלקטרית הקטנה שהמים שלו מסובבים היום","0290b614":"הנהר הקרחוני שאליו הוא מתנקז","d60dd44a":"🍅 Reykholt ו־Friðheimar","866e12e8":"עוברים ליד Friðheimar, Reykholt.","a267bb9b":"קצת מדרום לקוטב הצפוני לא אמור להיות אפשר לגדל עגבנייה — אז איסלנד מגדלת נתח גדול מהעגבניות והמלפפונים שלה על חום של הרי געש, ומדלגת על המשלוח.","63a4383c":"בקו הרוחב שלנו לא אמור להיות אפשר לגדל עגבנייה. אז בנינו חווה על הר געש והטסנו לכאן דבורים הולנדיות שינהלו אותה.","481e1c34":"חלופת מזג אוויר (אם החממות לא נראות): ״אם בחוץ אפור וקודר, חפשו את החממות שזוהרות בוורוד מבעד לעכירות — אלה עשרת אלפים שיחי עגבניות וכוח עבודה של בומבוסים הולנדים שמתעלמים ממזג האוויר לחלוטין.״","7f3ea4de":"**Reykholt** (״גבעת העשן״) שב־**Bláskógabyggð** הוא הכפר; **Friðheimar** היא חוות הכוכבת שלו — מתחם חממות גיאותרמי פעיל שבו אפשר לאכול צהריים בין הגפנים.","37653dc1":"בפנים גדלים בערך **עשרת אלפים שיחי עגבניות** תחת תאורת LED, על **מים גיאותרמיים** שמוזרמים ישר מהאדמה, ומואבקים בידי **בומבוסים הולנדים מיובאים** — לאיסלנד אין מאביק מקומי חזק מספיק לפרחי עגבנייה, אז היא הטיסה לכאן כוח עבודה.","31194dfd":"המנה החתומה היא **מרק עגבניות ללא הגבלה שנאכל מטר מהצמחים שייצרו אותו**. אותו חום געשי שמחמם את הבתים ב־Reykjavík, רק מכוון לארוחת הצהריים.","38fef673":"**החממה הראשונה באיסלנד שחוממה גיאותרמית הוקמה ב־1924**, ב־**Mosfellssveit**, אחרי שהמגדלים הבינו שמים גיאותרמיים יכולים גם **לחמם את בית הזכוכית וגם לעקר את האדמה בקיטור**. כאן ב־Reykholt החממה הראשונה קמה ב־**Reykholtshver ב־1932**, ו**תחנת הגננות הרצינית הראשונה הגיעה ב־1938**.","6ee949eb":"**Knútur Rafn Ármann** ו־**Helena Hermundardóttir** לקחו לידיהם את Friðheimar ב־**1995**, בנו את בית הגידול הגדול הראשון בין **1995 ל־2001**, ועברו ל**עגבניות כל השנה ב־2002**. לפני זה, עגבניות איסלנדיות פשוט נעלמו בחורף.","873fade3":"וזה החלק שרוב המדריכים מפספסים: **אנרגיה גיאותרמית נותנת לכם חום, לא אור.** בקו הרוחב הזה השמש בעצם מתפטרת בנובמבר, אז הצמחים רצים על **תאורת גידול חשמלית** לאורך החודשים החשוכים. חום **ועוד** אור, אף פעם לא חום לבד.","5eab13df":"**Reykholt** הוא בעצם אשכול שלם של עסקים כאלה — **Friðheimar**, **Espiflöt**, **Jarðarberjaland**, שפירושו המילולי **ארץ התותים** — בכפר של בערך **100 תושבים**.","9dd5109b":"גבעת העשן, הכפר שאנחנו עוברים לידו","4a6c20e3":"חוות הכוכבת שלו, החממות שבהן אוכלים מרק עגבניות בין הגפנים","ff2e836c":"המועצה האזורית ש־Reykholt יושב בה","8d2e047e":"🐎 הסוסים האיסלנדיים","2b3dfef4":"תסתכלו על הסוסים בשדה.","9dd1794f":"גזע סוסים שוויקינגים עוד היו מזהים — נשמר שלם במשך אלף שנה בזכות בידוד, חורפים קשים ודלת ייצוא חד־כיוונית.","42bf7aed":"אפשר להוציא סוס איסלנדי מאיסלנד. פשוט אי אפשר להחזיר אותו. המדינה מפעילה דלת חד־כיוונית לבעלי החיים שלה.","6829070f":"חלופת מזג אוויר (אם הסוסים לא נראים): ״אם הערפל הסתיר את הסוסים בשדה, לא מזיז להם — גזע קטן ופרוותי ששרד אלף חורפים איסלנדיים לא מתרגש מאחר צהריים לח אחד.״","be53c5cc":"ה**סוס האיסלנדי** קטן (**בערך 132–145 ס״מ**), פרוותי, מאריך ימים (לא פעם **30 שנה**), קשוח ובכנות גם בעל דעות משלו — ולפי מוסכמת הגזע והתעקשות לאומית, הוא **תמיד ״סוס״, לעולם לא פוני**.","734153a1":"לא נכנס לכאן דם חדש בערך מאז שנת **1000**, אז מדובר למעשה ב**אוכלוסייה סגורה וחסרת חסינות למחלות** — אחד הגזעים המקומיים הטהורים בעולם. המסורת אומרת שה־**Alþingi** טרק את דלת הייבוא בסביבות **982**; האיסור המתועד הוא מ־**1882** — והוא עדיין בתוקף.","cd390482":"לרוב הגזעים יש שלושה או ארבעה הליכים; לאיסלנדי יש עד **חמישה**, כולל ה**tölt** המפורסם — הליכת ריצה בת ארבעה פעימות כל כך חלקה שאפשר להחזיק כוס בירה מלאה בלי לשפוך. ההליכים הנוספים מקורם ב**מוטציה בגן אחד**.","06737035":"האוכלוסייה היא בערך **78,000** באיסלנד ובערך **195,000 בחו״ל** ביותר מ־30 מדינות — התפוצה גדולה פי שניים מהעדר בבית, ו**אף אחד מהם לא יורשה לחזור לעולם** (ביטחון ביולוגי שאוכף MAST, רשות המזון והווטרינריה).","282a3e0d":"הליכת הריצה החלקה בת ארבע הפעימות שאפשר לעבור אותה עם כוס בירה מלאה","2d4e34e2":"הפרלמנט של איסלנד","2b7d9c9b":"⛪ Skálholt","bb13c997":"ב־Skálholt.","3790843e":"מרכז הכוח של איסלנד לא נפל בגלל פלישה. הוא נפל בגלל קו שבר — והפוליטיקה גמרה את העבודה.","bf0c0b2d":"בירה בת 700 שנה, שנגמרה בגלל רעידת אדמה אחת וטופס מנהלי דני.","3c7e7fe7":"חלופת מזג אוויר (אם הכנסייה לא נראית): ״אם מזג האוויר בלע את הכנסייה, דמיינו אותה בכל זאת — מבנה לבן ופשוט על גבעה נמוכה, שהיה במשך שבע מאות שנה כל המוח של המדינה הזאת.״","2640e9cc":"**Skálholt** היה מושב ההגמון הראשון של איסלנד, שנוסד ב־**1056** — במשך 700 שנה המוח של המדינה: בישופים, **בית הספר הראשון** של איסלנד (Skálholtsskóli, 1056), חדר העתקות וספרייה, והכול ממומן ב**מעשר כנסייתי מובטח מ־1097**.","d158a53b":"הוא נתן לאיסלנד את **הקדוש היחיד שלה** — **Þorlákur Þórhallsson**, שהוכרז קדוש בידי ה־Alþingi ב־**1198** ורשמית מונה ל**קדוש המגן של איסלנד בידי הוותיקן ב־1984**; חג הזיכרון שלו ב־23 בדצמבר עדיין מעגן את חג המולד האיסלנדי.","60164ee2":"ה**רפורמציה** הגיעה ב־**7 בנובמבר 1550** עם עריפת ראשו כאן של **Jón Arason** — הבישוף הקתולי של *Hólar*, מושב ההגמון הצפוני — ושניים מבניו. ההשתלטות הלותרנית, נחתמה בדם על הדשא הזה.","cd6ec6cc":"**רעידת אדמה בעוצמה של בערך 7** (אזור הסייסמי של דרום איסלנד) ב־**1784** השטיחה את הקתדרלה; הדנים ניצלו את זה כדי לבטל את מושב ההגמון ולהעביר אותו לכפר דייגים בשם **Reykjavík** — רשמית, ב־**1801**. (הבישוף האחרון שגר ב־Skálholt, **Hannes Finnsson**, מת כאן ב־**1796**; האורות כבו לאט.) הכנסייה של היום היא **שחזור מ־1963** — שבו להקת הבלוז־רוק **Kaleo** הקליטה אחר כך שיר בהופעה חיה, כי איסלנד.","21fa9ef9":"הבישוף הראשון שלו, מ־**1056**, היה **Ísleifur Gissurarson** — זה שבנו ניהל את בית הספר למעלה ב־**Haukadalur**.","57bc6042":"המחוז שסביבו נקרא **Biskupstungur**, **לשונות הבישוף** — טריז האדמה שבין ה־**Hvítá** ל־**Tungufljót**. **tunga** היא לשון אדמה בין שני נהרות, והבישוף שבשם הוא זה שעל הגבעה.","207576a3":"הכנסייה קדמה לבישוף. אומרים ש־**Gissur hvíti** — אביו של Ísleifur עצמו — הקים את **הכנסייה הראשונה ב־Skálholt** אחרי ההתנצרות ב־**Alþingi בשנת 1000**, ו**Ísleifur Gissurarson הוסמך לבישוף הראשון של איסלנד ב־1056** ותפס שם את מקומו. Minjastofnun מכנה את המקום **המקום הראשי של איסלנד במשך כ־700 שנה**, ומושב ההגמון פעל **ברציפות מ־1056 עד 1801**, ועבר ל־**Reykjavík** רק בעקבות אסונות הטבע הגדולים של סוף המאה השמונה־עשרה.","22d8411f":"בית הספר פעל **מסוף המאה האחת־עשרה ועד 1785**, עם הפסקות קצרות. שבע מאות שנה של הוראה, בחווה.","be70cd13":"לעריפה של 1550 יש שמות וגם הקדמה. **Jón Arason** הוצא כאן להורג ב־**7 בנובמבר 1550** יחד עם בניו **Ari** ו**הכומר Björn** — ושנתיים קודם לכן, ב־**1548**, אנשי Skálholt הקימו **מצודה ממזרח לבית הקברות** כדי לבלום את התקפתו, ושרידיה עדיין ניתנים לזיהוי בשטח. ב־**1912** אנגלייה בשם **Disney Leith** מימנה **אנדרטה** לזכרו במקום שנחשב לנקודת ההוצאה להורג.","0b8b6335":"האתר נושא **עשרה מונומנטים ארכיאולוגיים מוגנים** ו**הרבה יותר ממאה** שרידים נוספים המוגנים מכוח גילם. את הקתדרלה שעומדת שם היום תכנן האדריכל הממשלתי **Hörður Bjarnason** והיא נחנכה ב־**1963** — ו־Skálholt קיבל בחזרה בישוף, **vígslubiskup**, ב־**1992**. (שבע מאות שנה כמרכז המדינה, ונגמר בגלל רעידת אדמה ולא בגלל פוליטיקה.)","cb6c2869":"החווה שהייתה הבירה, האוניברסיטה והקתדרלה של איסלנד במשך 700 שנה","f6034a4c":"הבישוף הקתולי של Hólar, שנערף כאן ב־1550","61a9747d":"הקדוש היחיד של איסלנד, שחג הזיכרון שלו ב־23 בדצמבר עדיין מעגן את חג המולד האיסלנדי","b5e7d820":"🎵 Grímsnes ו־Kerið","080f7291":"במכתש Kerið.","d7b72c28":"מכתש שמשמש גם כאמפיתיאטרון הטבעי הכי אקסקלוסיבי בעולם — נבנה בידי הר געש, הוזמן בידי זמר אופרה ובידי Björk צעירה.","61e909c6":"רוב המדינות עושות הופעות באצטדיונים. איסלנד עושה אותן בתוך הרי געש.","dc612bef":"חלופת מזג אוויר (אם המכתש לא נראה): ״אם הערפל מילא את המכתש, תפעילו דמיון — קירות אדומים בוהקים, אגם טורקיז בתחתית, ופעם אחת גם Björk צעירה מאוד ששרה מרפסודה באמצע.״","dba5885b":"**Kerið** הוא **מכתש געשי בן 5,000–6,000 שנה** — בערך **270 מ׳ אורך, 170 מ׳ רוחב ו־55 מ׳ עומק**: מספיק כדי לבלוע **בניין בן 17 קומות**.","57c34b5a":"הקירות הם **סקוריה אדומה** — גחלי בזלת עשירים בברזל שהברזל שלהם **התחמצן להמטיט**, כלומר בעצם חלודה, בעזרת מי תהום; תנו לזה עוד כמה אלפי שנים והוא ישחיר כמו השכנים שלו. האגם הוא **מי תהום** (7–14 מ׳ עומק) **בלי כניסה ובלי יציאה** — הוא פשוט עוקב אחרי מפלס מי התהום, וטורקיז כי המים בולעים קודם את האור האדום מול קרקעית כהה. יש בו אפילו חיים: **מחקר מ־2014 מצא 10 סוגים של זואופלנקטון**.","1bd8ba87":"**Kerið** הוא **gjallgígur** — מכתש סקוריה, שנבנה מגחלים. הוא **לא** מכתש פיצוץ. להתפרצות שיצרה אותו לא היה שום מקום למהר אליו.","5702a20e":"Kerið הוא **בבעלות פרטית** — של **Kerfélagið**, איגוד של בעלי הקרקעות המקומיים — והוא גובה **דמי כניסה קטנים מאז 2013**, וזה חריג במדינה שבה כניסה אל נוף היא בדרך כלל בחינם. הכסף הולך על השביל ועל **גרם המדרגות שיורד בקיר הצפוני**, וזה מה שמאפשר לכם לעמוד ממש על שפת המים.","68d0fb02":"הוא יושב בשדה הגעשי **Grímsnes** שעל השבר המערבי — הצפוני ביותר בשורה של ארבעה מכתשים, ופרי **אחת מתוך תריסר התפרצויות Grímsnes** בערך, שבנו את שדה הלבה **Grímsneshraun**. (כלומר לא מפץ גדול אחד — הוא נבנה לאט, כמו שאיסלנד עושה את רוב הדברים.)","25397c37":"האקוסטיקה של הקערה מצוינת, אז נערכו כאן **הופעות על במה צפה**. הראשונה והמפורסמת, ב**אוגוסט 1987**, משכה בערך **5,000 איש** ובראש המופע עמד בס האופרה **Kristinn Sigmundsson**; גם **Björk** בת ה־21 (אז בתחילת הדרך עם ה־Sugarcubes) הופיעה בתוכנייה — נכון, אבל היא לא הייתה הכוכבת הראשית שהגלויות מבטיחות.","aa9535c0":"המכתש האדום עם האגם הכחול בתחתית, בן 5,000 עד 6,000 שנה","b78192c1":"השדה הגעשי שהוא יושב בו, על השבר המערבי","ec4fa9d4":"הופיעה כאן ב־1987, בת 21, ושרה מרפסודה על האגם","64a75f7f":"בס האופרה שבאמת עמד בראש המופע של 1987","0f62bcfd":"⚡ נהר Sog","26ae6751":"חוצים את ה־Sog.","3e117df9":"שלוש תחנות כוח הידרואלקטריות קטנות על נהר קצר אחד — והן החזיקו את המדינה במשך חצי מאה.","013ad0fc":"הנהרות הגדולים מקבלים את הגלויות. ה־Sog בשקט הפעיל את האורות.","5e2476a9":"חלופת מזג אוויר (אם הנהר לא נראה): ״גם אם הגשם הסתיר את ה־Sog, תזכרו שהוא רק עשרים קילומטר אורך ופעם הוא סיפק חשמל לחצי מדינה — בדרך כלל דווקא השקטים עושים את העבודה האמיתית.״","8c5cfc6f":"ה־**Sog** יוצא מ־**Þingvallavatn** (האגם הטבעי הגדול באיסלנד) ומתחבר ל־Hvítá כדי ליצור את ה־Ölfusá.","5d312168":"קצר אבל עצום בנפח — **הנהר הצלול (מוזן מעיינות) הגדול ביותר באיסלנד**, בערך **110 מ״ק לשנייה** של מים מסוננים בקרחון וצלולים כמו אגם, מושלמים לייצור חשמל הידרואלקטרי.","33399c96":"שלוש תחנות — **Ljósafoss**, **Írafoss** ו־**Steingrímsstöð**, שנבנו **1937–1959** — יחד **בערך 90 מגה־ואט**, שסיפקו ביחד בערך **חצי מהחשמל של איסלנד** לאורך שנות ה־60 וה־70, עד שהתחנות הגדולות ברמות על ה־**Þjórsá** לקחו את התפקיד.","7f4c3f86":"ואיפה בעצם התחיל עידן החשמל האיסלנדי? לא כאן — ב**סדנת נגרות ב־Hafnarfjörður**: ב־**12 בדצמבר 1904** **Jóhannes Reykdal** הפעיל את **תחנת הכוח הראשונה** במדינה, שהאירה **15 בתים — ביניהם בית הספר ואולם ה־Good Templars — ובנוסף את הסדנה שלו עצמו וארבעה פנסי רחוב**, בדיוק בזמן לחג המולד. מנחל של נגר אחד ועד כל זה, בתוך חיים של אדם אחד.","c3a889cc":"התוצאה הייתה ביתית לגמרי. **Ljósafoss הכפיל פי ארבעה את כמות החשמל שעמדה לרשות אזור הבירה**, ו**משקי הבית ב־Reykjavík החליפו את תנורי הפחם בכיריים חשמליים.** עיר שלמה הפסיקה להריח מעשן בגלל נפילה בנהר שכמעט אף אחד מהם לא ביקר בו מימיו. גם **Steingrímsstöð** כמעט לא קרה — הסכר שלו **קרס באמצע הבנייה בסופה של 17 ביוני 1959.** לאבד סכר ביום העצמאות זה לא פרט שאיסלנדים אוהבים להעלות.","571500ee":"גם אחד הנהרות הטובים באיסלנד ל**פורל חום**.","e7698e26":"**Ljósafossstöð** נבנתה בין **1935 ל־1937**, ונפתחה עם **שתי מכונות בהספק כולל של 8.8 מגה־ואט** (שתיים של **4.4 מגה־ואט**). **מכונה שלישית של 5.8 מגה־ואט** נוספה ב־**1944**, והביאה אותה להספק מותקן של **14.6 מגה־ואט** — בערך **105 ג׳יגה־ואט־שעה** בשנה. גודל אף פעם לא היה העניין. **להיות ראשונה — כן.**","8cff83fb":"הסיבה שהמהנדסים אהבו את הנהר הזה: **ה־Sog הוא הנהר היחיד שמנקז את Þingvallavatn**, והאגם הזה מתנהג כמו מיכל איזון ענקי — הוא מסרב להציף והוא מסרב להתייבש. זה הופך את ה־Sog ל**אחד הנהרות היציבים ביותר במדינה**, וזה בדיוק מה שטורבינה רוצה.","f1e5c7b6":"הנהר באורך 20 ק״מ שאנחנו חוצים, שפעם סיפק חשמל לחצי איסלנד","8a9786e1":"הראשונה מבין שלוש תחנות הכוח שלו, 1937","0381043f":"האמצעית מבין שלוש תחנות הכוח, 1953","36af65aa":"האחרונה מבין השלוש, 1959","971ec11c":"הנהר הקרחוני שה־Sog מתחבר אליו","bce625f3":"נהר הניקוז הגדול ששניהם הופכים אליו","7bc1bc63":"הנהר הארוך ביותר באיסלנד, שהתחנות הגדולות שלו ברמות ירשו את ה־Sog","f1f14ff4":"Jóhannes Reykdal, הנגר שהדליק את המדינה","9be2ec22":"העיר שבה נדלקה תחנת הכוח הראשונה של איסלנד בדצמבר 1904","6e2f9f71":"🌊 Ölfusá","0b1c7678":"תסתכלו ימינה בשעה 1–2 — Ölfusá.","e9d9c792":"כל טיפת מים שירדה על המעגל הזהוב — קרחונים, גייזרים, אגמים — נסחטת בסוף דרך הערוץ האחד הזה.","bfea12f3":"ארבעה נהרות. ערוץ אחד. מאות שנים של אגרה בפרות ובבקלה. כל המים של המעגל הזהוב מובילים לכאן.","4504d48f":"חלופת מזג אוויר (אם הנהר לא נראה): ״אם אתם לא רואים את הנהר הגדול מימין, זה ה־Ölfusá — ארבעה נהרות שחובשים שם אחד, נושאים יותר מים מכל דבר אחר באיסלנד, אי־שם שם בתוך האפור.״","bac24ab7":"ה־**Hvítá** הקרחוני זורם דרומה מ־**Langjökull** ליד Gullfoss, ואוסף בדרך את **Tungufljót** ואת **Brúará**.","30086999":"ה־**Sog**, שמוזן ממעיינות, מנקז את **Þingvallavatn**. שני נהרות הגזע נפגשים ממש מעל Selfoss — ומשם הזרימה המשולבת היא ה־**Ölfusá**, **הנהר הגדול ביותר באיסלנד לפי ספיקה** (בערך **400 מ״ק לשנייה**, ומנקז אגן של בערך **5,760 קמ״ר**).","9ad7006d":"במשך מאות שנים זה היה המכשול האולטימטיבי: שום גשר בשום מקום, רק מעבורת ב־**Laugardælir** ששולמה ב**פרות או בבקלה** כדי להגיע לנמל ב־**Eyrarbakki**. כשהוא הציף באסון ב־**1623**, בישוף אחד האשים נחש נהר ענק — ״תולעת קרח״. (זו הייתה הצפה מפקק קרח. לנחש הייתה יחסי ציבור טובים יותר.)","a526f5da":"הנהר הגדול ביותר באיסלנד לפי ספיקה; ארבעה נהרות תחת שם אחד","b90f403c":"החצי הקרחוני, שזורם דרומה מ־Langjökull ליד Gullfoss","4e25b420":"החצי שמוזן ממעיינות, שמנקז את Þingvallavatn","bda3d79e":"מעבר המעבורת הישן, ששולם בפרות או בבקלה","8cdc347c":"אחד הנהרות שה־Hvítá אוסף בדרך","476290f3":"הקרחון שה־Hvítá מתחיל ממנו","d81d7d8d":"הנהר האחר שה־Hvítá אוסף","dc9be343":"🏗️ Selfoss","68a139cf":"אנחנו חוצים אותו ממש עכשיו — תסתכלו למטה. Ölfusárbrú.","36c37d86":"האויב שהפיל את הגשר של Selfoss לא היה צבא. אלה היו שתי משאיות עמוסות מדי וגשר שנבנה לימים קלים יותר.","46328a86":"המלחמה לא הצליחה לפוצץ את הגשר הזה. זוג משאיות חלב עשה את זה ביום שלישי אחר הצהריים.","025bf17c":"חלופת מזג אוויר (אם הנהר שמתחת לא נראה): ״אם הערפל הסתיר את המים שמתחתינו, הקדישו מחשבה לגשר שאנחנו חוצים — מלחמת עולם שלמה לא הצליחה להפיל אותו, אבל שתי משאיות חלב עמוסות מדי באותו אחר צהריים בהחלט הצליחו.״","24d6b24c":"ה־**Ölfusárbrú של 1891** — שנדחף באלת׳ינג בידי חבר הפרלמנט והבנקאי **Tryggvi Gunnarsson** — היה **גשר התלייה הראשון באיסלנד**, והעיירה Selfoss צמחה סביב המעבר. אין גשר, אין Selfoss.","fd8be6f1":"ב**מלחמת העולם השנייה** חיילים בריטים שמרו עליו יומם ולילה — מי שהחזיק במעבר היחיד מעל הנהר הגדול באיסלנד החזיק בדרום.","c4201c7e":"ואז ב**ספטמבר 1944**, אחרי 53 שנה, **שתי משאיות חצו בו זמנית**. כבלי הנשיאה המזרחיים לא עמדו במשקל המרוכז, **נקרעו, והפילו את הגשר לתוך הנהר**. שני הנהגים שרדו. גשר חלופי נבנה בערך תוך **חמישה חודשים וחצי** ונפתח ב־**21 בדצמבר 1945** — באמצע המלחמה, כי קו החיים של העיירה לא מחכה.","119e175c":"העיירה שצמחה סביב המעבר; אין גשר, אין Selfoss","d766ae44":"הגשר שאנחנו חוצים ממש עכשיו, גשר התלייה הראשון באיסלנד, 1891","188dfaff":"חבר הפרלמנט והבנקאי שדחף את הגשר באלת׳ינג","4a8f0d9d":"🧭 Ingólfur Arnarson","8ae207b3":"תסתכלו קדימה בשעה 12 — כביש הטבעת (Leið 1).","6d26fd24":"כביש הטבעת המודרני הוא הפרק האחרון של הסיפור הזה — הוא תופר יחד את החוף ש־Ingólfur התחיל.","16f4e0c2":"הסאגה מתחילה באיש שרודף אחרי שני עמודים. היא נגמרת באומה שלמה שנוסעת על הכביש שמשרטט את קו החוף שלו.","fe2fad17":"חלופת מזג אוויר (אם הכביש קדימה לא נראה): ״בכזה מזג אוויר אי אפשר לראות רחוק על הכביש, וזה דווקא מתאים — המתיישב הראשון של איסלנד בחר איפה לגור בכך שזרק שני עמודים מגולפים למים ועקב אחרי המקום שאליו נסחפו, בלי שום צורך בראות.״","b8ad1e0b":"אנחנו על **Leið 1**, כביש הטבעת — שהושלם רק ב־**1974** לרגל 1,100 שנה להתיישבות; לפני זה, להגיע ל־Höfn היה אומר עוד מאות קילומטרים על דרכי עפר.","9368fb51":"לפי הסאגה, **Ingólfur Arnarson** — שזכור כ**מתיישב הנורדי *הקבוע* הראשון** (לא האדם הראשון כאן; נזירים גאליים ונורדי בשם Náttfari הקדימו אותו) — זרק למים את **עמודי כס הכבוד** המגולפים שלו ונדר להתיישב בכל מקום שאליו ייסחפו.","9cd48190":"עבדיו **Vífill ו־Karli** מצאו אותם בסופו של דבר במפרץ שמהביל ממעיינות חמים, שאותו הוא קרא **Reykjavík**, ״מפרץ העשן״. (״החיפוש בן שלוש השנים״ שבסאגה מתנדנד אפילו בין המקורות הישנים — קחו את זה כסיפור, לא כשעון עצר.)","61e43736":"כביש הטבעת שאנחנו נוסעים עליו, שהושלם רק ב־1974","74e1f939":"המתיישב הנורדי הקבוע הראשון, שהלך בעקבות עמודי כס הכבוד שלו אל החוף","c5501437":"נמל הדרום־מזרח שלפני הכביש הזה נדרשו עוד מאות קילומטרים כדי להגיע אליו","07e75fdd":"🌋 Hveragerði","e5dc6254":"תסתכלו ימינה בשעה 3 — Hveragerði.","392407b5":"פיצה שנאפית בהר געש. בירה שמתבשלת בחום גיאותרמי. קניון שנבנה על סדק של רעידת אדמה. כן, הכול באותה עיירה.","22aa439f":"רוב העיירות מסתירות את האסונות שלהן. Hveragerði שמה את שלה בלובי וגבתה דמי כניסה.","51ec384c":"חלופת מזג אוויר (אם העיירה לא נראית): ״אם העיירה נבלעה בעכירות, חפשו את האדים שעולים בין הבתים — Hveragerði יושבת על צומת טקטוני כל כך תוסס שהיא בנתה מוזיאון סביב הסדק שרעידת אדמה קרעה דרך הקניון.״","d5fc669c":"Hveragerði יושבת על **צומת טקטוני משולש** בשולי **מערכת הגעש Hengill** — כל כך גיאותרמית שפומרולות וסירי בוץ מאדים **בין הבתים**. ב־**29 במאי 2008** האדמה שחררה פעמיים בתוך שלוש שניות — **זוג רעידות**: **Mw 5.8** מתחת ל־**Ingólfsfjall**, ואז **Mw 5.9** על **שבר Kross, בערך 5 ק״מ מערבה**, ובסך הכול **Mw 6.1 מורכב** שביקע מבנים ושינה מחדש את כל צנרת המעיינות החמים של העיירה.","3df1b097":"במקום להסתיר את זה, המקומיים בנו את התערוכה **Skjálftinn 2008** (״הרעידה״) בתוך מרכז הקניות **Sunnumörk** — בדיוק מעל בקע שהרעידה קרעה דרך הבניין. אפשר לעמוד על הסדק ולעלות על סימולטור הרעידות.","00b01156":"חום געשי זול הפך אותה ל**עיירת חממות** כבר משנות ה־20 (**החממה הראשונה באיסלנד שחוממה גיאותרמית** קמה ב־**1924**, ב־**Mosfellssveit**): עגבניות, מלפפונים, פרחים — ובמכללה לגננות גם **בננות ניסיוניות** (בערך טונה בשנה, פרויקט מדעי בלבד — איסלנד *אינה* רפובליקת בננות).","f1959df7":"לעיירה יש יום הולדת. היא התחילה ב־**1929**, על אדמות של החווה **Vorsabær** ב־Ölfus: באותו קיץ קמה תחנת החלב ב־**Breiðumörk 26**, והופיעו שני הבתים הראשונים — **Varmahlíð**, ובית קיץ ב־**Fagrihvammur** שבו התחילה ב־Hveragerði ה־**ylrækt**, גידול תחת זכוכית על חום גיאותרמי. תחנת חלב, שני בתי מגורים וחממה. זה כל סיפור המקור.","7ec202e7":"ה־**Garðyrkjuskóli ríkisins** ב־**Reykir** — המכללה הממשלתית לגננות — הוציאה **את הגננים המוסמכים הראשונים שלה באביב 1941**, ורובם יצאו ישר והקימו כאן משתלות משלהם. המספרים מספרים את זה טוב יותר מכל שם תואר: **שבע תחנות גננות ב־Hveragerði עד 1940, עשרים עד 1950.** גידול פרחים המריא לאורך שנות הארבעים והמקום הפך ל**blómabærinn**, עיירת הפרחים.","b7a07fe7":"בשביל פרופורציה: **בערך 140 איש בסוף 1941**, **בערך 400 עד 1946** — השנה שבה המועצה הוקמה רשמית — ו**בערך 3,350 היום, 3,344 בתחילת 2026.** השם עתיק בהרבה מהעיירה. **Hveragerði מופיע לראשונה ב־Fitjaannáll קצת לפני 1700**, בתיאור של מעיין חם מתפרץ **שהזיז את מקומו במהלך רעידות אדמה ב־1597**, וכבר בתיאור של Ölfus שנכתב ב־**1703** המעיינות היו בשימוש יומיומי ל**רחצה, בישול וכביסה.**","32b5bbe8":"Veðurstofa Íslands תיעדה את רעידת 2008 עד לדקה — **fimmtudaginn 29. maí kl. 15:45**, והכריזה באותו אחר צהריים על עוצמה **6.3** (ההודעה באנגלית של השירות המטאורולוגי מתייצבת על **6.1** לאירוע המורכב), עם מוקד ב־**Ingólfsfjall ב־Ölfus, בערך 5 ק״מ צפון־מערבית ל־Selfoss**, ומספר עצום של רעידות משנה אחריה. והדבר הכי טוב ב־**Sunnumörk** מלכתחילה לא נועד להיות מוצג בכלל: כשהמרכז היה בבנייה ב־**2003** **התגלה בקע של רעידת אדמה באדמה שמתחתיו**, ובמקום לסתום אותו הם **האירו אותו והשאירו אותו לראווה.** **הכניסה חינם** — משלמים רק אם רוצים סיבוב בסימולטור, שרץ על **יותר מ־6 בסולם ריכטר.**","d77025d0":"עיירת החממות מימינכם, עם אדים שעולים בין הבתים","394df800":"״הרעידה״, התערוכה שנבנתה מעל הסדק שרעידת האדמה של 2008 קרעה","d797cdd2":"מרכז הקניות שהבקע הזה עובר דרכו","5fc3fb65":"🏢 Hellisheiðarvirkjun","c5df9c85":"תסתכלו ימינה בשעה 2 — תחנת הכוח הגיאותרמית Hellisheiði.","2576764e":"בזמן שהעולם מתווכח על לכידת פחמן, איסלנד ממיסה את הבעיה במים, מתייקת אותה תחת ״סלעים״, וממשיכה הלאה.","d8f511ed":"המקלחת שלכם ב־Reykjavík הערב חוממה בידי אותו הר געש שבדיוק עכשיו מתייק CO₂ כחצץ מתחת לרגליים שלכם.","8359f957":"חלופת מזג אוויר (אם התחנה לא נראית): ״אם הערפל התמזג עם עמודי האדים מימינכם, בכנות אי אפשר להבחין איפה נגמר מזג האוויר ומתחילה תחנת הכוח — ובכל מקרה, זה מה שמחמם לכם את המקלחת הערב.״","25149aa8":"אנחנו על **מערכת הגעש Hengill**, צומת משולש נדיר של גבולות לוחות **על יבשה**. מים יורדים למטה, חוזרים בכמעט **300°C**, ומסובבים טורבינות — העמודים הלבנים הם **אדים**, לא עשן. היא נבנתה בשלבים בין 2006 ל־2011 עד ל־**303 מגה־ואט**, והיא **תחנת הכוח הגיאותרמית הגדולה באיסלנד**.","2b3d9f68":"אחרי החשמל, המים החמים שנשארים זורמים בצינורות ומחממים **יותר מחצי מאזור הבירה** — שום דבר לא הולך לאיבוד.","290e4c11":"דרך **CarbFix**, CO₂ מומס במים ומוזרם לתוך בזלת חמה, ושם **בערך 95% הופכים לסלע מוצק בתוך כשנתיים** (Matter et al., 2016). ממש ליד, מתקן **Mammoth של Climeworks** (2024) שואב CO₂ ישר מהאוויר — עד **36,000 טונות בשנה** — לאותו טיפול סלעי.","1b7c5dbb":"הטריק שמאפשר לכל זה לעבוד: הנוזל הגיאותרמי מתחתינו **חם, מאכל ועמוס במינרלים מומסים**, והוא לעולם לא מתקרב לרדיאטור שלכם. משתמשים בו כדי **לחמם מי תהום נקיים דרך מחליפי חום**, והמים הנקיים המחוממים האלה הם אלה שנוסעים לעיר. **מקבלים את החום בלי הכימיה.**","f141cbe8":"החצי השקט יותר של Hellisheiði הוא המים החמים: **200 מגה־ואט של תפוקה תרמית**, בערך **950 ליטר בשנייה** בצינור. מעבר לרכס יושבת האחות המבוגרת שלה, **Nesjavellir** — **Reykjavík קנתה את החווה ב־1965** והייצור בכל זאת התחיל רק ב־**1990**, כלומר **עשרים וחמש שנה** של קידוחים, בדיקות וויכוחים לפני שליטר מועיל אחד הגיע לאנשהו. היום היא פועלת ב**עד 120 מגה־ואט של חשמל** ו**עד 300 מגה־ואט תרמיים**, או כמו ש־Orka náttúrunnar מנסחת את זה ביחידה היחידה שמשק בית מבין: **1,640 ליטר מים חמים בכל שנייה.**","c56b2177":"Nesjavellir גדלה יפה. בסוף שנות ה־**90** דיווחו על אותה תחנה ל־Alþingi במספרים של **60 מגה־ואט חשמל ו־200 מגה־ואט חום** — **מאז תפוקת החשמל הוכפלה ותפוקת החום עלתה בחצי**, על אותה מדרון, עם אותו סלע. בין שתי התחנות, **Orka náttúrunnar מספקת בערך 60 אחוז מכל המים החמים באזור הבירה.**","59ccbd0a":"**Hengill** הוא לא פסגה, הוא **מערכת געשית באורך 50 עד 60 קילומטר** וברוחב **5 עד 10 קילומטרים**, שמשתרעת מ־**Selvogur** בדרום־מערב ועד **Þingvallavatn**. ההתפרצויות האחרונות שלו, לפני בערך **1,900 שנה**, יצרו את **Nesjahraun** וחלק מ־**Hellisheiðarhraun**; סבב מוקדם יותר, לפני **5,700 עד 5,800 שנה**, יצר את **Hagavíkurhraun**. הוא **מסווג כפעיל** — ותחנת הכוח הזאת נבנתה בדיוק על הבסיס הזה, לא למרותו.","cabd3b29":"בקנה מידה ארצי, **בערך 90 אחוז מהאנרגיה שמשמשת לחימום בתים באיסלנד מגיעה מגיאותרמיה** — זה הנתון של Orkustofnun ל־**2020.** המספר המקביל בבריטניה הוא בפועל **אפס.**","742cffe5":"תחנת הכוח הגיאותרמית הגדולה באיסלנד, עמודי האדים מימינכם","da6b2244":"מערכת הגעש שמתחתיה, צומת משולש של גבולות לוחות על יבשה","b5722c99":"הרמה והמעבר שהתחנה קרויה על שמם","316b916d":"⛰️ Kristnitökuhraun","99a8a406":"תסתכלו שמאלה בשעה 9 — Kristnitökuhraun, לבת הנצרות.","9a7d502c":"הדת של מדינה שלמה הוכרעה בשאלה גיאולוגית אחת, רגועה.","d4f2bf50":"הפגאנים טענו שהר געש מצביע. Snorri הצביע על כך שקלפי ההצבעה עתיקה יותר מהדת.","aa1d607e":"חלופת מזג אוויר (אם שדה הלבה לא נראה): ״גם כשהוא חבוי בערפל, הנקודה של שדה הלבה הזה שורדת — לפני אלף שנה ראש חמולה אחד הביט בסלע בדיוק בגיל הזה ושאל אילו אלים כעסו כשהוא נוצר, וזה הכריע את הדת של אומה שלמה.״","0c2956b9":"זוכרים את **Þorgeir מתחת לגלימה שלו** ב־Þingvellir הבוקר? אותה אספה, אותה שנה על חוד הסכין — שתי אמונות, שני קודקסים משפטיים, ומלחמת אזרחים אחת שמאיימת לפרוץ. שדה הלבה הזה הוא המקום שבו לסיפור ההוא צמחו שיניים.","36b5e789":"בשיא המתח שליח דיווח על **לבה שזורמת ב־Hellisheiði**. הפגאנים צעקו ״האלים כועסים!״","b25fbc75":"ראש החמולה **Snorri Goði** הצביע על הלבה העתיקה שמתחת לרגליים: *״על מה בדיוק כעסו האלים כשהסלע הזה נוצר?״* שקט — ואיסלנד בחרה בנצרות כדי לשמור על **חוק אחד** לכל האי. *(Kristni saga)*","50fd9cb4":"**וזה העניין — תסתכלו שמאלה: השדה הכהה בחלון הוא בדיוק הלבה ההיא.** זו השכבה העליונה והטרייה של מקבץ שלוש הזרימות **Svínahraun**, שתוארך בפחמן־14 לסביבות שנת **1000 לספירה**, כך שהוא **ירש את השם** מההתנצרות שהתרחשה במקביל. הערת שוליים מתאימה: היום פרויקט **CarbFix** משתמש בדיוק בבזלת הזאת כדי להפוך CO₂ לאבן — הסלע שפעם ״הוכיח״ זעם אלוהי סופג עכשיו פליטות תעשייתיות.","794ccbac":"לבת הנצרות משמאלכם, קרויה על שם ההתנצרות שהתרחשה במקביל אליה","c00e91a2":"מקבץ הלבה בן שלוש הזרימות שהוא יושב מעליו","f0500949":"ראש החמולה ששאל על מה כעסו האלים כשהסלע הישן נוצר","820e9028":"הרמה שממנה דווח שהלבה זורמת","d0ac015e":"דובר החוק שהפסק שנתן אחרי התנומה מתחת לגלימה נתן ללבה הזאת את שמה","f40d3fac":"⛰️ Rauðhólar","eacf4de3":"תסתכלו שמאלה בשעה 9 — Rauðhólar.","3f281ab5":"שני צבאות ועיר אחת חתכו את מעבדת המאדים של איסלנד וריצפו אותה למסלול המראה.","ebd31209":"שמונים חרוטים. כיתת לימוד אחת על מאדים. חצי מזה נמצא עכשיו מתחת למסלול ההמראה שלכם.","6d253121":"חלופת מזג אוויר (אם החרוטים לא נראים): ״אם אתם לא רואים את הגבעות האדומות הקטנות משמאלכם, אל תרגישו מרומים — אלה הרי געש מזויפים בלי שורשים, כל כך משכנעים שנאס״א חוקרת אותם כדי להבין את מאדים, והכול מבוזבז על הערפל של היום.״","8c4006d8":"אלה **פסאודו־מכתשים** (באיסלנדית *gervigígar*) — ובשם המדויק, **חרוטים חסרי שורש**: אין צינור מאגמה, אין שורשים. הרי געש מזויפים.","9605f5af":"**לפני בערך 5,000 שנה** לבה מהר הגעש המגן **Leiti** גלשה על ביצת **Heiðmörk**; מים כלואים הפכו בבת אחת לאדים, ובפיצוץ **פריאטומגמטי** **פרצו בחזרה החוצה** דרך הלבה המותכת — וקפאו באמצע ההתפוצצות כסקוריה אדומה (תחמוצת ברזל — חלודה).","2b218e10":"במקור היו כאן בערך **80 חרוטים**. מכיוון שחרוט חסר שורש נוצר רק במקום שבו לבה פגשה מים, גיאולוגים קוראים את אלה של איסלנד כתבנית ל**מאדים** — החרוטים חסרי השורש ב־**Athabasca Valles** מצוטטים כראיה למים קבורים על הכוכב האדום.","9b639887":"ואז, מעשית, הצבא הבריטי כרה כאן חצץ כדי לבנות את **שדה התעופה של Reykjavík** במלחמת העולם השנייה; החפירות נמשכו שנים. המקום הוכרז כמוגן ב־**1974**.","63513cd9":"מבט אחד שסוגר מעגל לפני העיר: מאחורי החרוטים שוכן **Elliðavatn** — ועל לשון יבשה נמוכה בתוכו נמצא **Þingnes**, **הבית השני של ה־Kjalarnesþing**, האספה האזורית שפגשתם הבוקר. היא המשיכה להתכנס שם עד **המאה ה־13** — כך שאתם יוצאים מהמעגל הזהוב דרך מתחם הפרלמנט המקורי של המדינה.","92998d4a":"וגם סיפור החשמל נסגר בדיוק כאן: בעמק **Elliðaár** שלמטה עמדה **תחנת הכוח הראשונה של Reykjavík (1921)** — 17 שנה אחרי **המתקן של Reykdal בבית המלאכה לנגרות** שהדליק את הנורות הראשונות במדינה ב-Hafnarfjörður. מנחל ליד בית מלאכה ועד הר געש שמתייק CO₂ בתור חצץ: מאה שנות חשמל איסלנדי, ואתם בדיוק נסעתם את כל הקשת.","36793886":"החרוטים האדומים הקטנים משמאלכם; הרי געש מזויפים בלי שורשים","f36c060a":"הלבה מהר הגעש המגן Leiti שגלשה על הביצה","38b34cae":"הביצה שהלבה גלשה עליה, שהמים הכלואים בה פוצצו את החרוטים החוצה","195f9a54":"האגם שמאחורי החרוטים, שבו נמצא מקום האספה הישן","dde56354":"לשון היבשה הנמוכה שבה המשיך ה-Kjalarnesþing להתכנס עד שנות ה-1200","f1e0ca05":"אספת האזור שדיברנו עליה הבוקר, במשכנה השני","17d1c244":"עמק הנהר שבו עמדה תחנת הכוח הראשונה של Reykjavík","10ad3335":"הנגר מ-Hafnarfjörður שהמתקן שלו מ-1904 הדליק את הנורות הראשונות במדינה","8a1ca964":"תחנת האוטובוסים BSÍ → Hvolsvöllur","6a798c8d":"באיסלנד הנוף מסתכל עליכם בחזרה — ולפעמים גם מגיש תלונה לבישוף.","af121de2":"נולד ב-**15 באוקטובר 1885** ב-**Efri-Ey** שב-**Meðalland**, בדרום איסלנד — **הילד ה-9 מתוך 13** (להורים שלו בבירור היה כוח סוס). נשלח למשפחה אומנת במזרח, ל-**Geitavík** שב-**Borgarfjörður eystri**, ושם בפיורד עדיין קוראים לו **“Jói í Geitavík.”** צבעים היו יקרים מדי בשבילו, אז הוא צייר עם **דם עגלים, פיח וצבע צמר** — ואז יצא לים.","31506a29":"אנשי הצוות ראו את הסקיצות שלו, **העבירו כובע ואספו כסף**, ואיגוד הדייגים השלים את החסר. **1911**: **האקדמיה המלכותית בלונדון טרקה לו את הדלת.** הדחייה הייתה בעצם שינוי מסלול — **1912** ל-**קופנהגן** ול**אקדמיה המלכותית הדנית** (סיים ב-**1917**).","0bcb753e":"כשחזר הביתה הוא צייר את איסלנד כשהוא כורע על הברכיים, עם **האזוב והלבה שלושה אינץ' מהאף שלו**, ונשבע שהוא רואה **שדונים ואת העם הנסתר** בתוך הסדקים. (באיסלנד זו לא אבחנה — זו קריירה.)","f191f29f":"**1914**: תמונת המזבח שלו בכנסיית **Bakkagerði** מראה את ישו דורש מעל **Álfaborg**, סלע השדונים, ומאחור **Dyrfjöll**. הבישוף סירב לברך אותה — **יותר מדי שדונים, פחות מדי ישו** — ולכן היא תלויה שם עד היום, **לא מקודשת** בכל הדרה. תמונת מזבח שנייה, שנפסלה בתור “גסה ומכוערת”, נקנתה בידי **Halldór Laxness** בשביל **Gljúfrasteinn** (נעבור שם בהמשך). איש אחד, שתי תמונות מזבח, **אפס בישופים משוכנעים.**","9e1274d8":"הוא צייר בערך **5,000 יצירות — ואת רובן פשוט נתן במתנה**, ומת כשכמעט **לא היה לו כלום.** הבלוק האפור ההוא ב-Klambratún הוא **Kjarvalsstaðir**, **מוזיאון האמנות הראשון באיסלנד שנבנה במיוחד בשביל זה** (1973); ומאז **1995** הפרצוף שלו מופיע על **שטר ה-2,000 króna** — הדייג היחיד בהיסטוריה שקיבל **קידום להילך חוקי.**","e26b1208":"מקום הולדתו, בדרום איסלנד","7e7e5dfc":"המקום שאליו נשלח לגדול אצל משפחה אומנת","485d977c":"החווה של המשפחה האומנת; “Jói í Geitavík”","2083fa4d":"הכנסייה שבה תלויה תמונת המזבח שלו","e3268abd":"סלע השדונים שבציור","b0296b1c":"הבית של Laxness, שבו תלויה תמונת המזבח שנפסלה","540d733f":"המטבע של איסלנד; ברבים krónur","b6b79fb2":"Ölgerðin Egill Skallagrímsson","d0b9cc59":"נוסדה ב-**17 באפריל 1913** בידי **Tómas Tómasson** בשני חדרי שינה במרתף של בית שכור ב-Reykjavík — בהתחלה רק **תמצית לתת עם 1% אלכוהול** — ונקראה על שם **Egill Skallagrímsson**, הלוחם-משורר שפעם חרז את עצמו מעל גרזן התליין (ה-*Höfuðlausn*, “פדיון הראש”) והיה מסוגל להשכיב אולם שלם מתחת לשולחן. מיתוג שאפתני.","0cba5bf6":"שנתיים אחר כך איסלנד אוסרת על **כל אלכוהול** (1915) — אז Tómas מפליג ל**קופנהגן ולגרמניה (1915–17) כדי ללמוד בישול בירה בכל זאת**, ומתאמן על מוצר שהמדינה שלו בדיוק הוציאה מחוץ לחוק. יין מתגנב בחזרה ב-**1922**, משקאות חריפים ב-**1935**, אבל **הבירה נשארת אסורה עד 1989** — כי היא נתפסה כ**דנית**, ולגמוע לאגר דני בזמן שנלחמים בדנמרק על עצמאות הרגיש כמו בגידה.","afd3aab4":"המייסד","37850a5b":"יום הבירה, 1 במרץ","23c97c23":"Elliðaárdalur ו-Paradísardalur","efaaadb1":"זה נראה כמו פארק לטיול של יום ראשון. בפועל זה אתר בנייה בן 5,000 שנה שאף אחד מעולם לא סגר.","39a4b5cf":"הר געש חצה את הנהר. הוויקינגים תפסו עליו בעלות. הבריטים ביצרו אותו. והנהר עדיין עובד שעות נוספות כדי לבטל את כל זה.","932c7990":"כל העמק עוצב מחדש לפני **~5,000 שנה**, כשהתפרץ **Leiti**: הלבה זרמה למטה, פגשה את הנהר ו**חצתה אותו לשניים**. לפני כן נהר אחד; אחרי כן שניים. כל מפל כאן הוא **פרויקט בן 5,000 שנה** של הנהר, לנסר לעצמו דרך חזרה דרך בזלת מוצקה עד הים.","db92d11b":"ה-Elliðaá הוא כמעט הנהר היחיד בעולם שעובר בעיר בירה **ויש בו נדידת סלמון אטלנטי פראי** — בערך **1,500–2,500** דגים דוחפים במעלה הזרם ליד הרצים, כל קיץ. Reykjavík כל כך התאהבה שהיא **קנתה את כל הנהר ב-1906.** (העיר שלכם קונה פארקים. אנחנו קנינו נהר.)","21145de3":"קילומטר אחד של עמק הספיק להכיל **מפעל צמר משנות ה-1750**, **בריכת הטבעה ב-Skötufoss** לנשים שהורשעו ב“עבירות מוסר”, פורעי חוק במנהרות הלבה, **צריפי פח בריטיים ממלחמת העולם השנייה**, ותחנת כוח הידרואלקטרית בת מאה — **Elliðaárstöð (1921)**, שעדיין מזמזמת.","85a9cfef":"והדבר הכי איסלנדי מכולם: **צינור שהתפוצץ ב-1998** הציף את העמק, ובסוף שבוע אחד **שטף 10,000 שנה של היסטוריה קבורה בחזרה אל אור היום.** כאן אפילו האינסטלציה עוסקת בארכיאולוגיה.","e34d22fd":"המפל של בריכת ההטבעה","4acdd215":"Rauðhólar","206c64da":"תסתכלו ימינה בשעה 3 — Rauðhólar.","67ed7e70":"אלה **פסאודו-לועות** (באיסלנדית *gervigígar*) — ליתר דיוק **חרוטים חסרי שורש**: אין צינור מאגמה, אין שורשים. הרי געש מזויפים.","1f0cb1c5":"ואז, בפרקטיקה: הצבא הבריטי כרה כאן חצץ כדי לבנות את **שדה התעופה של Reykjavík** במלחמת העולם השנייה; החפירות נמשכו שנים. הוכרז אתר מוגן ב-**1974**.","56ea5710":"Kristnitökuhraun","30203f3b":"בסביבות שנת **1000 לספירה** נפגשו מנהיגי איסלנד ב-**Þingvellir** כדי להחליט: האלים הנורדיים הישנים או הנצרות? שתי דתות פירושן שתי מערכות חוקים — וכמעט מלחמת אזרחים.","19fd2153":"שדה הלבה הזה הוא השכבה הטרייה שמעל ערימת **Svínahraun** בת שלושת הזרמים, שתוארכה בשיטת הפחמן הרדיואקטיבי לסביבות שנת **1000 לספירה** — כלומר הוא **ירש את השם** מההתנצרות שקרתה בדיוק אז. הערת שוליים מתאימה: היום פרויקט **CarbFix** משתמש בדיוק בבזלת הזאת כדי להפוך CO₂ לאבן — הסלע שפעם “הוכיח” זעם אלוהי מנקה עכשיו פליטות תעשייתיות.","3d4c8d65":"ערימת הלבה שהוא יושב מעליה","dcc261dc":"הרמה השוממה / המעבר","2ea6753b":"Hellisheiðarvirkjun","c906c094":"אנחנו נמצאים על **מערכת הגעש Hengill**, מקרה נדיר של **צומת משולש של גבולות לוחות על יבשה**. מים יורדים למטה, חוזרים בטמפרטורה של כמעט **300°C**, ומסובבים טורבינות — העמודים הלבנים הם **אדים**, לא עשן. היא נבנתה בשלבים בין **2006–2011** עד **303 MW**, והיא **תחנת הכוח הגיאותרמית הגדולה באיסלנד**.","74f112fe":"אחרי שמפיקים את החשמל, המים החמים שנשארו זורמים **27 ק״מ** בצינורות מבודדים ומחממים **יותר מחצי מאזור הבירה** — שום דבר לא הולך לאיבוד, ו-Reykjavík אף פעם לא צריכה לחפש סוודר.","49f582db":"בפרויקט **CarbFix** ממיסים CO₂ במים ומזרימים אותו לתוך בזלת חמה, ושם **~95% הופכים לסלע מוצק תוך כשנתיים** (Matter ואחרים, 2016). ממש ליד, המתקן **“Mammoth” של Climeworks** (2024) שואב CO₂ ישר מהאוויר — עד **36,000 טונות בשנה** — בשביל אותו טיפול אבן.","5316d196":"Ölfusá","6760eb13":"כל טיפה שנפלה על המעגל הזהב — קרחונים, גייזרים, אגמים — נדחסת בסוף דרך התעלה האחת הזאת, באורך 25 ק״מ.","6f155280":"המעגל הזהב מקבל את הגלויות. הנהר הזה הוא המקום שבו כל היום נגמר בשקט.","c61fbe28":"רק **~25 ק״מ אורך**, ובכל זאת **הנהר הגדול באיסלנד לפי ספיקה** — בערך **423 מ״ק בכל שנייה** מאגן ניקוז של **~5,760 קמ״ר**. לא הארוך ביותר; פשוט זה שבשום פנים ואופן לא הייתם מצליחים לחצות.","a68b5b6c":"זו בעצם **מערכת אחת שמורכבת מארבע**. הנהר הקרחוני **Hvítá** זורם דרומה מ-**Langjökull** ליד **Gullfoss**, ואוסף בדרך את **Tungufljót** ואת **Brúará**; ונהר המעיינות **Sog** מנקז את **Þingvallavatn**, האגם הטבעי הגדול באיסלנד. הם נפגשים ממש מעל **Selfoss**, ומשם ממשיכים כנהר אחד — **Ölfusá**.","cf09f601":"הוא עוקב אחרי **אזור השברים הסייסמי של דרום איסלנד**, ומזגזג לאורך קווי שבר. לידו נמצא **Þjórsárhraun** — בן ~**8,600 שנה**, בשטח של ~**950 קמ״ר**, **זרם הלבה הבודד הגדול ביותר של כל תקופת ההולוקן, בכל מקום על פני כדור הארץ**.","14fa4424":"במשך מאות שנים הוא היה **המכשול האולטימטיבי**: אי אפשר לחצות אותו ברגל, אין גשר, רק מעבורת ב-**Laugardælir** ששילמו עליה ב**בקר או בבקלה**, כדי להגיע לנמל ב-**Eyrarbakki**. כשהוא הציף הכול באסון ב-**1623**, בישוף האשים נחש נהר ענק — “תולעת קרח”. (בפועל זה היה **שיטפון של סתימת קרח**; פשוט לנחש היו יחסי ציבור טובים יותר.)","22923e57":"מעבר המעבורת הישן","4287703b":"“נהר הגשר”","fbb707b8":"“נהר הלשון”","3b7e19f3":"זרם הלבה הגדול","1c403473":"Hveragerði","e6ffabce":"פיצה שנאפית בהר געש, סלט שגדל על אדים, ומוזיאון שבנוי על סדק של רעידת אדמה — הכול באותה עיירה.","23e4aaeb":"Hveragerði יושבת על **צומת טקטוני משולש** בקצה **מערכת הגעש Hengill** — גם גיאותרמי *וגם* סייסמי, שילוב קשוח בשביל מיקוד אחד. פומרולות וסירי בוץ רותחים מבעבעים **בין הבתים.**","e84354a1":"ב-**29 במאי 2008** רעידת אדמה בעוצמה **Mw 6.3** — “דואט”, שני שברים במרחק של בקושי **2 ק״מ** זה מזה — טלטלה את העיירה בתאוצה של עד **~0.88 g** (קרוב ל-1 g: האדמה דוחפת חזק כמו כוח הכבידה), פיצחה בניינים ושינתה מהיסוד את מערכת המעיינות החמים. במקום להסתיר את זה, המקומיים בנו את התערוכה **Skjálftinn 2008** (“הרעידה”) בתוך מרכז **Sunnumörk**, ממש מעל השבר — אפשר לעמוד על הסדק ולעלות על סימולטור הרעידות.","6ef4f342":"חום געשי זול הפך אותה ל**עיירת חממות** כבר משנות ה-1920 (החממה הגיאותרמית הראשונה ב-**1923**) ול**גינת הירק** של איסלנד: עגבניות, מלפפונים, פרחים — ובמכללה לגננות גם **בננות ניסיוניות** שנשתלו בערך ב-**1950**: בערך **טונה בשנה, אף פעם לא מסחרי**. איסלנד *אינה* רפובליקת בננות — היא פשוט מחזיקה בטונת הפרי הכי מנופחת באירופה.","9409fa9c":"תערוכת רעידת האדמה של 2008","ba6fa08c":"המרכז שבו היא נמצאת","0ee255d5":"מערכת הגעש שמתחת לעיירה","c38410a4":"Ingólfur Arnarson","8252d431":"לפי הסאגה, **Ingólfur Arnarson** השליך למים את **עמודי כיסא הכבוד** המגולפים שלו ונשבע להתיישב בכל מקום שאליו ייסחפו. העבדים שלו, **Vífill ו-Karli**, מצאו אותם במפרץ שהעלה אדים ממעיינות חמים, והוא קרא לו **Reykjavík**, “מפרץ העשן”. (“החיפוש בן שלוש השנים” שבסאגה מתנדנד גם בין המקורות העתיקים עצמם — קחו את זה כסיפור, לא כסטופר.)","12e6b4dc":"ניפוץ מיתוס: הוא לא היה **הראשון** כאן. נזירים אירים (ה-**Papar**) כבר היו באיסלנד ועזבו כשהגיעו הפגאנים; ונורדי בשם **Náttfari** נשאר כאן שנים קודם לכן. התואר האמיתי של Ingólfur צר יותר — **המתיישב הנורדי ה*קבוע* הראשון לפי מסורת הסאגות** — והוא קיבל את הגביע כי המשפחה שלו ניהלה אחר כך את הפרלמנט וכתבה את הפרוטוקול.","24107d1d":"הנזירים האירים שהגיעו לכאן ראשונים","11f89e1f":"הנורדי שנשאר כאן קודם","4eee6df8":"הנמל בדרום-מזרח","f13b5bf6":"Selfoss","3c0b4f2a":"תסתכלו ימינה בשעה 3 — Ölfusárbrú.","1c4ef4e8":"האויב שהפיל את הגשר של Selfoss לא היה צבא. אלה היו שני נהגי חלב והחלטה גרועה בעניין כבל גרירה.","f1dbc34e":"העיירה **קיימת רק בזכות הגשר.** **Ölfusárbrú משנת 1891** — שנדחף דרך ה-Alþingi בידי חבר הפרלמנט והבנקאי **Tryggvi Gunnarsson** — היה **גשר התלייה הראשון באיסלנד**; לפניו אי אפשר היה לחצות את Ölfusá, אז המסחר הצטופף ליד ראש הגשר ו**Selfoss צמחה מסביבו.** צריף הבנייה הישן, **Tryggvaskáli**, הוא עדיין הבניין הוותיק ביותר בעיירה.","bf89fa35":"ואז ב-**ספטמבר 1944**, אחרי 53 שנה, משאית חלב ניסתה לגרור משאית חלב תקועה ולחצות איתה בו-זמנית. **כבלי הנשיאה המזרחיים לא עמדו במשקל המרוכז, נקרעו, והפילו את שתי המשאיות אל תוך הערוץ.** שני הנהגים שרדו — אחד מהם נאחז ב**ארגז המשאית עד שנסחף לחוף** ליד הכנסייה.","19241a25":"גשר חלופי נבנה תוך כ-**חמישה חודשים וחצי** ונפתח מחדש ב-**21 בדצמבר 1945** — באמצע המלחמה, כי עורק החיים של העיירה לא מחכה, והמוטה הזה נושא אתכם עד היום.","96e39221":"האיש שדחף את הגשר ב-Alþingi","c974feeb":"הבניין הוותיק ביותר בעיירה","e8ee5e37":"Þjórsá","13387e26":"תסתכלו ימינה בשעה 1–2 — Þjórsá ומישור ההצפה שלו.","6727940c":"כל חצייה כאן עוברת מעל צינור הניקוז הראשי — והסוללה הגדולה ביותר — של נתח רציני מעמוד השדרה של איסלנד.","cc6dafab":"ל-Selfoss הייתה הדרמה של משאיות החלב. Þjórsá הוא **הכבד-משקל הסבלני** — מזיז מים בכמות של רמה שלמה, וחצי מרשת החשמל הארצית, אל הים.","9b2a60cf":"**Þjórsá** (“נהר השור”) יוצא מכיפת הקרח **Hofsjökull** וזורם **230 ק״מ** עד הים — **הארוך באיסלנד** — ומנקז אגן של **7,530 קמ״ר** בספיקה של בערך **383 מ״ק לשנייה**. לא נהר שחותרים בו בהיסח הדעת.","e9e8df0d":"באמצע הזרם יושב האי **Árnes**, שבתקופת ההתיישבות אירח **Þing** משלו — אספה מקומית. תנו לאיסלנדי סלע קל להגנה בתוך נהר מהיר, והאינסטינקט הראשון שלו יהיה לקיים עליו ישיבה.","d05cc49d":"הערוצים הרחבים והמסועפים בשדות הם **נתיבי שיטפון**: כשהקרחונים נמסים מהר, Þjórsá מתפרש על המישורים במקום להישאר בנימוס בערוץ אחד. העמק שלו, **Þjórsárdalur**, הוא אזור חוות ש**Hekla השכנה קברה יותר מפעם אחת** באפר.","ca9b7a4b":"הוא עושה **יותר עבודה חשמלית מכל נהר אחר באיסלנד**: **שש תחנות כוח** על מערכת Þjórsá–Tungnaá (Búrfell הראשונה, **1969**) מזינות את הרשת — בעיקר את **מפעלי האלומיניום**, שהם הסיבה שמדינה של 380,000 תושבים מייצרת כל כך הרבה חשמל. התחביב המודרני כאן הוא להתווכח על סכירה שלו.","b8c130eb":"הנהר הארוך באיסלנד","7fa8e67b":"כיפת הקרח שהוא מנקז","d2cae10d":"אי האספה","f35c2e25":"Hella","ab41315b":"תסתכלו שמאלה בשעה 9 — המערות של Hella.","95bfa511":"חלק מהארכיאולוגיה העתיקה והמוזרה ביותר במדינה — הוכחה שבאיסלנד ההיסטוריה לא נמצאת רק על פני השטח. לפעמים היא חצובה בתוך המדרון שאתם חולפים לידו.","f7d0ab94":"רוב העיירות שומרות את ההיסטוריה שלהן במוזיאון. Hella שומרת חלק ממנה במרתף — ולא לגמרי בטוחה מי נכנס לגור שם ראשון.","3f2ab863":"בתוך אבן החול הרכה שליד נהר **Ytri-Rangá** חצובה קבוצה של **מערות מעשה ידי אדם**, בחלקן **צלבים** פשוטים ו**ספסלי אבן** חצובים בקיר.","2b79f268":"תיאוריה פופולרית קושרת אותן ל-**Papar** — הנזירים האירים שגם **Íslendingabók** וגם **Landnámabók** אומרים שהיו באיסלנד *לפני* הנורדים, וברחו ברגע שספינות הדרקון הופיעו באופק. מפתה, אבל בואו נהיה הוגנים: התיארוך **שנוי במחלוקת**, ו**שום ממצא ארכיאולוגי לא אישר מקור קדם-נורדי** — קחו את זה כרמז, לא כעובדה סגורה.","4759bb53":"העיירה עצמה היא חדשה יחסית: **Hella נוסדה ב-1927**, כשמישהו בנה חנות כלבו *וגם* בית מטבחיים ליד גשר הנהר — כי אין דבר שמעגן יישוב כמו לקנות מצרכים ולשחוט את הכבש באותה עצירה.","1214d115":"היום זו תחנת העצירה עם **הרי געש באופק** (Hekla קצת במעלה הכביש), **סוסים בשדות** (**Rangárvellir**, ארץ הסוסים), ואולי גם **נזירים במרתף**.","a0600d41":"הנזירים האירים","937aa779":"הנהר שליד המערות","bbbe457c":"מחוז גידול הסוסים","f2fb6a26":"Keldur","a94eaa5b":"תסתכלו שמאלה בשעה 10 — חוות הכבול Keldur.","0db19a6d":"זו לא חווה עתיקה וחמודה. זו **אדריכלות ביטחונית של ימי הביניים**, בנויה ישר לתוך המדרון.","ca106f3d":"Keldur היא בעצם חדר מיגון ורכב מילוט מתקופת הוויקינגים, מחופשים לחוות כבול נעימה.","435bccb7":"**Keldur** הוא **בית החווה העתיק ביותר שעדיין עומד באיסלנד** — אולם משובח **בסגנון המסדרון**, שהמוזיאון הלאומי מתארך ל**סוף המאה ה-12**, כלומר הוא נבנה בזמן שהסאגות עוד נחיו במציאות ולא נכתבו.","b5330cab":"זה היה אחד ממושבי ה-**Oddaverjar**, השבט שהסאגות מכנות **“מלכי הדרום,”** והוא עומד בדיוק בלב ארץ **Njáls saga** — הדייר הראשון שלו, Ingjaldur Höskuldsson, מוזכר בשמו בסאגה עצמה.","1c8a4bf9":"קירות הכבול העבים לא היו קישוט — הם היו **טכנולוגיית אקלים**: לשמור אנשים, בעלי חיים ואוכל בחיים לאורך חורפים ארוכים ורטובים, כמעט בלי עץ לבזבז.","3c158795":"**מנהרה תת-קרקעית** מוסתרת יורדת מהאולם לכיוון נחל — לא רומנטי, פרקטי לגמרי: **דרך מילוט** אם אויבים ינסו להצית את הבית כשכולם ישנים בפנים. בשכונה הזאת זו לא הייתה פרנויה. תשאלו את Njáll.","d9c00cfd":"“מלכי הדרום”","6dced86f":"גיבור הסאגה","9aa0ac73":"Hvolsvöllur","4ac7bc25":"תסתכלו קדימה בשעה 12 — Hvolsvöllur.","4ff2833c":"לרוב העיירות יש תחנת דלק וסופרמרקט. לזאת יש שטיח קיר קהילתי של **בגידות, שריפות וייעוץ משפטי גרוע** — ומוזיאון שמחובר בחוטים להתפרצות הבאה.","0b755032":"ברוכים הבאים לשכונה של Njáll — שבה רשימת הקריאה המקומית משמשת גם כמפת רציחות.","682f94c4":"**Hvolsvöllur** היא תחנת התדלוק האחרונה עם שירות מלא לפני Vík, שתולה בלב ארץ **Brennu-Njáls saga** — סאגת המשפחה **הארוכה, העקובה מדם והבנויה בקפידה** ביותר באיסלנד. החוות והגבעות הנמוכות סביבכם הן הבמה האמיתית שלה.","338f7857":"היא **נכתבה בערך ב-1270–1290** אבל מתרחשת בסביבות **שנת 1000**, והסצנה המרכזית שלה — ה-**brenna**, שריפת **Njáll**, אשתו **Bergþóra** ובניהם בסביבות **1011** — ממוקמת בידי החוקרים ב-**Bergþórshvoll**, השטח המישורי ממש ממזרח לכאן. *משחקי הכס*, רק שחצי מהשחקנים היו צריכים גם לחזור הביתה לקצירת החציר.","74202928":"בעיירה עצמה: **מרכז הסאגות** עם **שחזור של אולם ויקינגי**, דגם של **Þingvellir בסביבות שנת 1000 לספירה**, ושטיח הקיר הארוך של **Njáls saga**, שנרקם בידי מקומיים ומבקרים — אופרת סבון של ימי הביניים בחוטים צבעוניים.","ec22667e":"ממש ליד, **מרכז LAVA** (נפתח ב-**2017**) יושב במכוון בין **ארבע מערכות געש פעילות** — Hekla, Katla, Eyjafjallajökull ואיי ווסטמן, כולן בטווח של 50 ק״מ — עם סייסמוגרף חי שקורא את הקרקע מתחת לרגליים שלכם.","1ac8edd2":"“Njáll השרוף”","c5dcda53":"החווה של Njáll, מקום השריפה","23e2c8c3":"“שריפת בית” בסאגות","5875fdcd":"Hvolsvöllur → Sólheimajökull","83ef7963":"Vestmannaeyjar","3e838039":"תסתכלו קדימה בשעה 12 — איי ווסטמן.","9c595e21":"אחד המקומות הבודדים בעולם שבהם עיירה נלחמה בהר געש **עם מי ים ומשאבות** — ויצאה מזה עם נמל טוב יותר.","7fac7f35":"הר הגעש ניסה לסגור את הנמל. המקומיים ענו: “נשמח לשדרוג, תודה.”","753930ef":"ממש אחרי חצות ב-**23 בינואר 1973** נפער **סדק באורך 1.6 ק״מ** במרחק של בקושי 200 מ׳ מהעיירה, על האי **Heimaey**, והר געש חדש לגמרי — **Eldfell**, “הר האש” — התחיל לזרוק לבה על הרחובות המזרחיים.","70fd9953":"מה שהציל אותם היה מזג האוויר: סערה ביום שלפני השאירה את **כל צי הדיג בנמל**, ולכן מתוך כ-**5,300 תושבים, בערך 5,000 פונו תוך שמונה שעות בערך** — לאיסלנד **אין צבא**, אז הדייגים ניהלו את הפינוי בעצמם.","3d38d6e4":"ההתפרצות נמשכה **חמישה חודשים** וקברה בערך **400 מבנים** — פומפיי האיסלנדית, וכמה מהבתים נחפרו בחזרה במוזיאון **Eldheimar**. כדי להציל את הנמל, הצוותים שאבו **מיליוני ליטרים של מי ים מצפון האטלנטי** על זרם הלבה המתקדם, במשך שבועות, והלבה שהתקררה השאירה את פתח הנמל **עמוק ומוגן יותר מקודם.**","2282b2cc":"מישורי Landeyjar","24b7dd9c":"תסתכלו קדימה בשעה 12 — ה-sandur של Landeyjar.","b7492d71":"לגור כאן זה להשלים עם זה שהחצר האחורית שלכם היא **תעלת הניקוז הטבעית של קרחונים גדולים וכועסים** — כל חווה, כל גדר וכל גשר נבנים כשה-**jökulhlaup** נמצא איפשהו בראש.","0b75538e":"“אין כאן כלום,” אומרים. מתחתיכם: קרקעית ים עתיקה. לפנים: מישור סחף קרחוני. משמאל: קו חוף רפאים. ושם רחוק: זירת רצח מהסאגות. זה די הרבה כלום.","011f9ccb":"זה נראה כמו “סתם שדות שטוחים”, אבל אתם חוצים מניפת **משקעי שיטפון** ענקית, שנבנתה גרגר אחרי גרגר בידי נהרות קרחוניים — בעיקר **Markarfljót** — שמסתערים החוצה מהרמות.","a435edd8":"השם מסגיר את זה: **Landeyjar פירושו “איי יבשה”** — כתמי דשא שהתרוממו מתוך הביצה והחול. פעם גלים התגלגלו בדיוק במקום שבו עובר הכביש הזה, והים הגיע עד **קו המצוק שמשמאלכם**. ואז היבשה עלתה, הנהרות המשיכו לשפוך חול, וקו החוף **צעד דרומה, קילומטר אחרי קילומטר.**","f8162371":"המישור ה“ריק” הזה הוא גם **הבמה של Njáls saga**: **Bergþórshvoll**, המקום שבו משפחתו של Njáll נשרפה חיה בסביבות **1011**, נמצא כאן בין שדות החציר. שטוח, שקט — ולפני אלף שנה, הכתובת של שריפת הבית המפורסמת ביותר באיסלנד.","18bb9dd8":"חוות הסאגה שנשרפה","3101f5bd":"Markarfljót ו-Hlíðarendi","fe3305e2":"תסתכלו שמאלה בשעה 10 — Hlíðarendi מעל Markarfljót.","756027f8":"בשביל האורחים זו חווה אי שם במרחק. בשביל איסלנדים זו **צומת מוסרית** שעדיין עומדת בנוף כמעט אלף שנה אחר כך.","86cf0b9a":"שם בחוץ: דשא וכבשים. בסאגות: איש שבחר בנוף שלו על פני החיים שלו — ואישה שזכרה בדיוק איך פגעו בה.","0290f51f":"מולכם, **Markarfljót** זורם **~100 ק״מ** אל הים משתי **כיפות קרח שיושבות על הרי געש חיים** — **Eyjafjallajökull** ו-**Mýrdalsjökull** — ובגלל זה הוא מפסיק מדי פעם להיות נהר והופך ל-**jökulhlaup**. ב-**2010** מהנדסים **פרצו במכוון את סוללת כביש הטבעת** כדי לתת למי ההפשרה של ההתפרצות לעבור ו**להציל את הגשר.** מקריבים את הכביש כדי לשמור על המעבר.","004dde78":"מוחבא במדרונות הרחוקים נמצא **Hlíðarendi**, ביתו של **Gunnar** מהסאגה של **Njáll** — הלוחם הטוב באיסלנד, שיכול היה לקפוץ את גובהו שלו במלוא השריון, אחורה.","e4d36e69":"אחרי שנגזרה עליו גלות, Gunnar יצא לדרך, הביט לאחור ואמר את המשפט שכל איסלנדי מכיר: *“Fögur er hlíðin — יפה המדרון… אני לא אלך מכאן.”* המבט האחד הזה עלה לו בהכול: הוא **חזר, נשאר, ונהרג** כשהגן על החווה שלו.","45564b37":"והמכה בבטן: כשהוא היה נצור ומיתר הקשת שלו נחתך, הוא ביקש מאשתו **Hallgerður** שתי מחלפות משיערה כדי לשזור מיתר חדש. היא סירבה — נקמה על סטירה שקיבלה שנים קודם — ונתנה לו למות.","868ca107":"הגיבור של Hlíðarendi","cef295c0":"אשתו","94dad663":"Eyjafjallajökull","a0c62882":"תסתכלו שמאלה בשעה 10–11 — Eyjafjallajökull וחוות Þorvaldseyri.","943a05ae":"שם למעלה: קרחון שליו מעל חווה מגלויה. בזיכרון: ההר שהפך את שדות התעופה של אירופה לאתרי קמפינג.","0c68c8d7":"חקלאי כאן חפר אפר מתוך מי השתייה שלו, בזמן שמנכ״לים של חברות תעופה התמוטטו 2,000 ק״מ משם.","c8d6c441":"**Eyjafjallajökull** — הר געש שכבתי בן **~800,000 שנה**, פסגה בגובה **1,651 מ׳**, מתחת לכיפת קרח שהצטמקה לכ-**66 קמ״ר** — יושב שם ונראה כמו מכסה לבן ומסודר מעל שדות ירוקים.","addd5b69":"בקנה מידה געשי **2010 הייתה קטנה: VEI 4, רק ~0.27 קמ״ק של אפר.** אבל היא ירתה **עמוד עשן בגובה 8–9 ק״מ** ישר לתוך **זרם הסילון** — הר געש קטן בדיוק במקום הלא נכון — והחלקיקים הזכוכיתיים הופכים מנועי סילון ל**מתקני התזת חול יקרים מאוד.**","34107856":"התוצאה: **השבתת התעופה הגרועה ביותר באירופה מאז מלחמת העולם השנייה** — בערך **10 מיליון נוסעים תקועים**, המרחב האווירי של כ-**20 מדינות** נסגר, וכ-**100,000 טיסות בוטלו** במשך שישה ימים. אירופה למדה שהרי געש לא קוראים לוחות זמנים.","86020148":"בחוות כמו **Þorvaldseyri** למרגלותיו, **500–800 איש פונו בן לילה** כשמי ההפשרה שטפו מהקרח; חקלאים **חלבו פרות עם מסכות נשימה**, גירדו אפר מהגגות, ואז בנו מרכז מבקרים — אם הר געש כותב לכם מחדש את השנה, אפשר גם למכור את הסיפור.","9a0e09ef":"השאלה שאורחים שואלים כל פעם: האם זה מפעיל את **Katla** מהשכנות? ההתפרצויות של 920, 1612 ו-1821 עשו בדיוק את זה — אבל ב-**2010 Katla נשארה סגורה.** נורת אזהרה, לא הדק.","f80d1c90":"החווה שגרפה אפר ומכרה את הסיפור","0472c39d":"Rútshellir","30eab80f":"תסתכלו שמאלה בשעה 10 — Rútshellir, המערה החצובה במצוק ליד Drangshlíð.","a6d4f3c6":"מערה שהייתה בית, רפת, מחסן דגים, זירת רצח ומרדף נאצי אחרי כלום — הכול בחור אחד בסלע.","3a987cc7":"לרוב החוות יש סככה. ל-Drangshlíð יש מערה בת אלף שנה עם חור התנקשות ייעודי בתקרה.","426efc69":"**Rútshellir** היא אחת **המערות הגדולות ביותר מעשה ידי אדם באיסלנד** — אולם מקומר באורך של בערך **20 מ׳ ובגובה 2.5 מ׳**, שנחצב מהמצוק הרך של **Drangshlíðarfjall**, בערך **3 ק״מ ממערב ל-Skógafoss.** מזמן טוענים שהיא **מבנה המגורים העתיק ביותר מעשה ידי אדם ששרד באיסלנד.**","e4f8966f":"האגדה: בריון בשם **Rútur** — טרול, שודד או צ׳יפטן רע, בחרו מה שמתאים לכם — גר כאן, והעבדים שלו **חצבו חור מתחת למדף השינה שלו ודקרו אותו ברומח מלמטה** בזמן שישן. גם מת הוא הפחיד אותם: אחד הרוצחים, **Björn**, ברח להר **Bjarnarfell**, שעדיין נושא את שמו.","b49884e3":"זה מתועד, לא רק בשירה — רשום ב**פנקס הקרקעות של Árni Magnússon (1714)** ובספר המסעות משנת **1756**. **צלב חצוב בתקרה** גורם לאנשים לנחש נזירים אירים לפני הנורדים — לא מוכח, אז מגישים את זה בתור “יש שחושבים”.","0b023e84":"הפרק הכי מוזר: ב-**1936 ה-Ahnenerbe של הימלר** — יחידת המדע המזויף של ה-SS — חיפשה כאן, משוכנעת שתמצא מקדש נורדי עתיק. הם מצאו אסם.","cfaa72e2":"המערה של Rútur","b2a85ab2":"החווה / ההר","1e58d7a9":"המקום שאליו ברח הרוצח","83878a0b":"יחידת ה-SS מ-1936","e8c0972f":"Sólheimajökull","07261733":"בקרחון Sólheimajökull.","c3c35169":"דיאגרמות מספר הלימוד על קרחונים, סחיפה ושינוי אקלים — פרושות ממש לפניכם. **מספיק להצביע, אין צורך לצייר.**","bff0b437":"לא צריך להעביר כאן הרצאה על אקלים. פשוט מצביעים על המקום שבו היה פעם הקרח — ו**הקרחון החסר** מדבר בעצמו.","1ae0b1b2":"שביל חצץ מושך אתכם לכיוון **Sólheimajökull**, לשון יציאה של **Mýrdalsjökull** — **כיפת הקרח ה-4 בגודלה באיסלנד** — תקועה בין הרי הגעש **Katla** ו-**Eyjafjallajökull**, כש-Katla קבורה ממש מתחת.","312f69cb":"מקרוב הקרח בכלל לא לבן — הוא מפוספס ב**רצועות אפר שחורות** מהתקפי הזעם של שני הרי הגעש, כמו מכחול מפויח שנגרר על פני תיעוד שכבתי של כל השכונה.","7204d698":"מלפנים יושבת **לגונה קדם-קרחונית בכחול-ירוק** עם קרחונים קטנים שמתנתקים ממנה; הצבע הוא **קמח קרחוני**, סלע שנטחן כל כך דק שהוא הופך את המים לאבק אבן נוזלי. הלגונה הזאת **חדשה** — הלשון **נסוגה בערך 40 מ׳ בשנה**, בערך אורך של אוטובוס בכל קיץ, וההליכה אליה נעשית ארוכה יותר ויותר.","f6a31938":"שלטים לאורך השביל מסמנים לאן החזית הגיעה *פעם*: “כאן… וכאן… וכאן.” בדיוק עכשיו הלכתם **עשרות שנים של נסיגה בכמה דקות.**","cf94735d":"Sólheimajökull → Reynisfjara","10d117cf":"שרידי ה-DC-3","7a805d71":"תסתכלו ימינה בשעה 2 — הרחק על מישורי החול.","321dbe43":"**שכבה מודרנית על גבי הגיאולוגיה**: Katla בנתה את ה-sandur, חיל הים האמריקאי החנה עליו מטוס בטעות, והרשתות החברתיות עשו את השאר.","0a948902":"מהאוטובוס אתם בעיקר רואים שחור ריק. הסיפור האמיתי: צוות שנתקע בהצטברות קרח מעל קרחון, גלש עד החוף בלי מנועים, ו**כל השבעה שרדו** — במטוס שכולם מתעקשים לקרוא לו בשם הלא נכון.","96b335e8":"כולם קוראים לו “DC-3”. הוא לא. הוא **Super DC-3 של חיל הים האמריקאי (דגם Douglas R4D-8 / C-117D)** — אותה משפחה, רק בן הדוד המנופח שהלך לחדר כושר. הוא נושא את השם הלא נכון כבר חמישים שנה.","77a6591b":"ב-**21 בנובמבר 1973** הוא טס מ-**Höfn ל-Keflavík**, וכש**קרח חנק את שני הקרבורטורים מעל כיפת הקרח Vatnajökull** שני המנועים כבו. ניפוץ מיתוס: **לא** “נגמר לו הדלק” — הוא נסתם בקרח והפך, במילים של הטייס המשנה, ל“דאון עם עודף משקל אדיר”.","bea0bd49":"הטייס פנה **דרומה לכיוון החוף** והנחית אותו על החול השחור. **כל שבעת אנשי הצוות יצאו מזה על הרגליים.** חיל הים פירק את החלקים השימושיים והשאיר את גוף המטוס החשוף.","0151feba":"במשך עשרות שנים זה היה ציון דרך מקומי ושקט; ואז הגיעו **קליפ של ביבר (2015)** והלהיט הבוליוודי *Dilwale* שצולם כאן, ואינסטגרם עשתה את השאר. מכוניות נאסרו ב-**2016**, אז היום הולכים **מסלול של 4 ק״מ לכל כיוון** על קרקעית אוקיינוס עתיקה כדי לגעת במטוס בלי כנפיים. וזו לא בדיחה במזג אוויר רע: במישור **אין שום מחסה**, ו**שני מבקרים מתו מהיפותרמיה** ליד ההריסות בסערה בינואר 2020.","0c1f5ff7":"מישור הסחף","703f08b1":"Pétursey","3e2ff9a7":"תסתכלו שמאלה בשעה 10 — ההר התלול והמבודד.","e074e313":"גיאולוגיה, סאגה, קדוש וחייל — הכול ערוך זה על זה על גוש אחד של אפר קפוא.","512d1c32":"לרוב ההרים יש קצה ערך בוויקיפדיה. **ל-Pétursey יש קורות חיים.**","6aa5c222":"**Pétursey** (“האי של פטרוס”) עשוי **móberg** — סלע פלגוניט של אפר ורסק שנוצר כשהר געש **מתפרץ מתחת לקרח או לים**; מאגמה חמה פגשה מים קרים, התנפצה באמצע הפיצוץ, והתלכדה לקירות התלולים האלה. אותו מתכון בדיוק כמו **Drangurinn** הסמוך.","c42f8ae4":"במשך חלק גדול מתקופת ההולוקן האוקיינוס האטלנטי באמת הקיף אותו, ומלחים השתמשו בו כ**ציון דרך** — עד שהחול השחור של **Katla** מילא לאט את הרווח והשאיר אותו תקוע בתוך היבשה. השם הישן שלו פירושו המילולי **“האי הגבוה.”**","39b382d3":"השם שבו משתמשים היום בא מ**מקדש מימי הביניים לכבוד פטרוס הקדוש** על הפסגה — אתר עלייה לרגל קתולי לפני הרפורמציה.","9c652f17":"במלחמת האזרחים של **Sturlungaöld**, בערך **200 אנשים חמושים ביצרו את הפסגה** כמצודה — **Þórðar saga kakala** מתעדת אותה כמקום מקלט. ב**מלחמת העולם השנייה** הבריטים השתמשו שוב באותה פסגה עם שדה ראייה של 360° בתור עמדת תצפית. במצוקים עדיין מקננים **יסעורים ופאפינים**; ובגבעה, איך לא, גרים **שדונים.** שתי חוות יושבות למרגלותיו: **Eystri-** ו-**Vestri-Pétursey.**","7468d816":"“האי של פטרוס”","51efa32d":"סלע פלגוניט של אפר ורסק","83ab7afa":"תקופת מלחמת האזרחים, בערך 1220–1264","1824c7bf":"החווה המזרחית","5d9bb71d":"החווה המערבית","4ca1e764":"Skeiðflatarkirkja","cf4caf1b":"תסתכלו שמאלה — כנסייה קטנה עם גג אדום בין השדות.","176bb1cf":"הסיפור של האדריכלות האיקונית של Reykjavík לא מתחיל בעיר. הוא מתחיל ב**חוות כמו זאת**, בצל הרי געש.","b1cd6256":"אם תצמצמו קצת את העיניים, אתם כמעט יכולים לראות את Hallgrímskirkja **מסתתרת בתוך** הכנסייה הקטנה הזאת עם הגג האדום — היא רק הייתה צריכה בן עם דמיון גדול ומשכורת של אדריכל המדינה.","9b7b417c":"את הכנסייה הצנועה הזאת תכנן ובנה הנגר האמן **Samúel Jónsson** (יליד 1864) — אחת מאותן כנסיות כפריות פשוטות ואיתנות, שנבנו כדי לספוג רוח, גשם ואפר בלי להתרגש.","0049777a":"בנו **Guðjón Samúelsson** (יליד **1887**) גדל כאן והפך ל**אדריכל המדינה הראשון של איסלנד** — האיש שמאחורי **Hallgrímskirkja**, כנסיית עמודי הבזלת על הגבעה ב-Reykjavík, וגם מאחורי **התיאטרון הלאומי** ו**הבניין הראשי של האוניברסיטה.**","c0349adf":"רמז להמשך היום: Guðjón גם תכנן את **המגדלור מ-1927 ב-Dýrhólaey**, הצוק שנעבור לידו ליד Vík. האבא בנה את הכנסייה הקטנה; הבן בנה את קו הרקיע.","1fb0e8bc":"Hallgrímskirkja **הוזמנה ב-1937** אבל ההקמה שלה הייתה מרתון — היא **קודשה סוף סוף ב-1986, 36 שנה אחרי ש-Guðjón מת ב-1950.** הוא מעולם לא ראה את יצירת המופת שלו גמורה.","eef3eb02":"הבן, אדריכל המדינה","7202b1e1":"הכנסייה ב-Reykjavík","f012b7e5":"האב, שבנה את הכנסייה הזאת","0ac7cfee":"Dýrhólaey","259e3ab6":"תסתכלו ימינה בשעה 2 — הצוק הגבוה עם המגדלור.","4a0f93af":"עצירת הוראה מושלמת: מישורים קרחוניים, איים ישנים וסחיפת חוף פעילה, כולם נראים ב**סיבוב ראש איטי אחד.**","a5bc8c21":"Dýrhólaey הוא הציר שבו **הרי הגעש, ה-sandur והאוקיינוס** לוחצים ידיים — ומתווכחים מי בנה את קו החוף הזה.","ba00211f":"**Dýrhólaey** (“אי גבעת הדלת”) נולד מתחת למים לפני ~**100,000 שנה** בהתפרצות תת-ימית — חצי טוף (**Háey**), חצי בזלת (**Lágey**) — ואז הגלים חצבו **קשת ים** טבעית ענקית, ה“דלת” שבשם, מתחת ל**מצוקים בגובה ~100 מ׳.**","8ac5fae5":"למעלה יושב מגדלור שנראה כמו טירה: **אור החוף הראשון של איסלנד והחזק ביותר שלה**, נראה למרחק של **43 ק״מ (27 מייל ימי)** אל תוך הים — המגדל הראשון ב-1910, וזה מבטון **מ-1927 של Guðjón Samúelsson**, אותו אדריכל של הכנסייה מכמה עצירות אחורה.","e9b85be5":"מלמעלה אפשר לקרוא את כל **מסדרון Katla** — ה-sandur מאחור, מחטי **Reynisdrangar** מלפנים, והאטלנטי מטיח את עצמו בבזלת. זו **עיר של עופות ים**, ולכן חלקים ממנה **נסגרים בעונת הקינון** בשביל הפאפינים (שמורה מוגנת מאז **1978**).","3a6fe80a":"הרבה זמן קראו לו **הנקודה הדרומית ביותר של היבשת** — אם כי טכנית **השיטפון של Katla ב-1918 בנה את Kötlutangi קצת יותר דרומה.** הר הגעש הזיז לעצמו את קו הסיום. ב-**אוקטובר 1993** הטייס **Arngrímur Jóhannsson** וחבר הפרלמנט **Árni Johnsen** העיפו מטוס קל דרך הקשת — שלושה מעברים, כדי להוכיח שהראשון לא היה מזל.","2df91052":"“אי גבעת הדלת”","0126faa4":"החצי מטוף והחצי מבזלת","e1685559":"עמודי הים שלפנינו","99f191ae":"הנקודה הדרומית ביותר, החדשה יותר","095cb2eb":"Reynisfjara","b87adf26":"Reynisfjara ו-Reynisdrangar","75d812e1":"בחוף החול השחור.","7f5726a3":"עצירה אחת: חול שחור, בזלת עמודים, סחיפת גלים, וזוג טרולים ששכחו לשים לב לשעה.","19bc922f":"הטרולים קפאו עם הזריחה. האוקיינוס עדיין לא הפסיד ויכוח.","08952c28":"מתחת לרגליים שלכם: **חול געשי שחור** ודק — בזלת שפגשה את הים, התנפצה, ונטחנה לגרגרים. **בלי צדפים, בלי אלמוגים, רק הר געש כתוש.**","04e8d47e":"בצד אחד, **Hálsanefshellir** — המערה הרדודה עם קיר **עמודים משושים** שנראה כמו עוגב, מתחת למצוק **Garðar**: לבה שהתקררה כל כך לאט שהיא התכווצה ונסדקה לעמודים מסודרים בעלי שש פאות, בדיוק אותו טריק כמו ב-Giant's Causeway.","8afc496b":"בתוך המשברים עומדים **עמודי הים Reynisdrangar**, שארית של צוק ישן שבו הבזלת הקשה החזיקה מעמד בזמן שהמצוק הרך יותר נאכל — ה“עמוד” שבסוף הרצף סדק-מערה-קשת-עמוד. באגדה, העמודים האלה הם **שני טרולים וספינה**, שהזריחה תפסה אותם באמצע גניבה והפכה אותם לאבן. הטרולים כאן פעילים רק בלילה; אור יום הוא הקריפטונייט שלהם.","7c9a152e":"והחלק הרציני נשאר רציני: **גלי הפתע הרגו לפחות חמישה אנשים עד 2022, ועוד מקרה מוות ב-2025** — ובגלל זה הותקנה **מערכת אזהרה ברמזור** ב-**2022.** הפולקלור הוא האטרקציה הבטוחה יותר.","04da9eeb":"מצוק הבזלת","4c411eb4":"Reynisfjara → Vík","122368f8":"Katla","210fbebf":"תסתכלו שמאלה בשעה 9–10 — Mýrdalsjökull, כיפת הקרח שמכסה את Katla.","130b2abd":"הר הגעש המסוכן ביותר בחוף הדרומי לא נראה כמו הר געש. הוא נראה כמו קרחון.","1e2b2074":"האזהרה הכי מנומסת באיסלנד: **הדבר הכי רועש שהיא עושה הוא לחכות.**","7778d43b":"מתחת לקרח ההוא יושבת **Katla** — **קלדרה ברוחב ~10 ק״מ**, פסגה בגובה **1,512 מ׳** — אחד מהרי הגעש הגדולים והכועסים ביותר באיסלנד. הכיפה מעליה היא **Mýrdalsjökull**, **כיפת הקרח ה-4 בגודלה באיסלנד** (~**595 קמ״ר**), שמיכת בידוד בעובי **200–700 מ׳** מעל כבשן. העובדה שהיא תת-קרחונית היא כל הסכנה: היא לא סתם זורקת אפר, היא **ממיסה את הקרחון בבת אחת והופכת אותו לשיטפונות.**","6fa6c5df":"היא הוציאה **יותר מ-20 התפרצויות מאז שנת 930 לספירה**, בדרך כלל **VEI 4–5** — גדולות יותר מההופעה של השכנה המפורסמת Eyjafjallajökull ב-2010. הגדולה האחרונה, ב-**1918**, נמשכה **24 יום** ושפכה כל כך הרבה סחף שיטפוני שהיא **דחפה את החוף הדרומי החוצה בערך 5 ק״מ.** הר געש שמייצר קרקע חדשה.","fc3245e2":"המרווח המשוער הוא **כל 40–80 שנה**; והגדולה האחרונה הייתה לפני יותר מ-**100 שנה** — כך שבכל קריאה כנה היא **מאחרת.** המערכת שלה יצרה גם את **Eldgjá** בסביבות שנת **939 לספירה**, אחד משיטפונות הלבה הגדולים ביותר של 2,000 השנים האחרונות, והיא מדליפה כל כך הרבה CO₂ גם כשהיא רדומה, שמחקר אחד דירג אותה בין **מקורות ה-CO₂ הגעשיים הגדולים בעולם.**","e20cb94c":"כשהיא מתפרצת מתחת לקרח היא יוצרת **jökulhlaup** — שיטפון קרחוני שיכול לדחוף **עד ~300,000 מ״ק בשנייה** אל הים, מהר יותר מסוס דוהר. העיירה שלפנינו, **Vík**, מתאמנת על זה כבר עשרות שנים.","e741b67e":"הר הגעש","a3bb67af":"כיפת הקרח שמכסה אותה","d718d4ee":"שיטפון פרץ קרחוני","a117225c":"העיירה שלפנינו","15fa6d92":"Vík í Mýrdal","be35ca33":"Víkurkirkja","5bb79f30":"תסתכלו שמאלה בשעה 10 — הכנסייה עם הגג האדום מעל העיירה.","a971114c":"הבניין הכי יפה בעיירה הוא גם **ציוד הבטיחות** הכי פרקטי שלה.","9e8c3955":"זה המקום היחיד ב-Vík שבו הנוף של האוקיינוס מרגיש שליו — כי אתם יודעים שאתם עומדים על הקרקע הבטוחה היחידה בעמק.","d5a0037e":"**Víkurkirkja**, ש**קודשה ב-1934**, יושבת גבוה על הגבעה מסיבה אחת: **Katla.**","f355ed31":"אם הר הגעש יתפרץ מתחת ל-**Mýrdalsjökull**, ה-**jökulhlaup** שייווצר יכול למחוק את כל הכפר — והכנסייה הזאת עומדת על **הקרקע היחידה שגבוהה מספיק** כדי להישאר מעל המים.","d53cfa9a":"כל תושב מאומן **לרוץ לכנסייה הזאת** ברגע שהצפירות נשמעות, והתרגילים מניחים שאולי יש להם רק בערך **15 דקות** להתפנות. ב-Vík, “לרוץ לכנסייה” זו לא דרשה — זו מדיניות חירום.","87c8fe7a":"תסתכלו קדימה בשעה 12 — Vík מעבר לגבעה.","37ef1965":"Vík היא המקום שבו הפסקות קפה, התרעות של משמר החופים ו**טינות בנות אלף שנה מהסאגות** חולקים את אותו נוף של הר געש.","122c5fd5":"עיירת חוף נמנמנית. אם Katla מתחילה לצעוק, מחליפים את החוף בכנסייה ומקווים שזה רק תרגיל.","70e69f0d":"**הכפר הדרומי ביותר ביבשת איסלנד** — בערך **300 איש** בכפר עצמו, **~750** במחוז הרחב יותר — פרוס לאורך החוף, כש-**Víkurkirkja** חונה בבטחה למעלה על הגבעה. **בלי נמל טבעי**, זה היה היסטורית מקום שבו חתרו עם סירות דרך המשברים היישר מהחוף הפתוח.","be28eb83":"היא גם **המקום הכי חם באיסלנד** (ממוצע שנתי של ~**5.3°C**) וגם **הכי גשום** (~**2,250 מ״מ** גשם — בערך פי שלושה מ-Reykjavík). המילה “חם” עובדת שם קשה מאוד.","5d150546":"ב-**1918 Katla** התפרצה מתחת לקרח ושלחה לים **jökulhlaup** כל כך אדיר שהוא **דחף את קו החוף החוצה בערך 3 ק״מ ב-Kötlutangi**, וקבר את הכול תחת חול טרי.","a1d6b776":"ממזרח, **Hjörleifshöfði** — צוק מהסאגות שפעם ישב מול ים פתוח — תקוע היום **בתוך היבשה**, כשהרווח התמלא בשקט על ידי מאה שנים של חול שחור של Katla. הכנסייה מעל העיירה היא נקודת ה“**תרוצו לכאן אם Katla מתעוררת**” הרשמית.","120d3d92":"Hjörleifshöfði","10821600":"תסתכלו קדימה בשעה 1 — ההר העצום עם הפסגה השטוחה באופק.","cac83c2c":"ההיסטוריה של איסלנד לא התחילה בשלום. היא התחילה ב**מרד עבדים, בנקמת דם** — ובסוכנת בית נקמנית שגרה בתוך הקרח.","23b3c55f":"סיפורי הייסוד של רוב המדינות הם פסלים ונאומים. של איסלנד הוא גופה, דוב מזויף — ואישה שהפכה להר געש.","946489d6":"**Hjörleifshöfði** — **צוק móberg בגובה 221 מ׳** — קרוי על שם **Hjörleifur Hróðmarsson**, **אח הדם המושבע של Ingólfur Arnarson, המתיישב הראשון של איסלנד**. השניים **הפליגו לכאן יחד בסביבות 874**, ואז נפרדו: Ingólfur נתן לאלים לבחור את ביתו והלך אחרי עמודי כיסא הכבוד שלו עד Reykjavík; ו-Hjörleifur — ש**סירב להקריב קורבן לאף אל** — עגן בצוק הראשון. **תל הקבורה שלו עדיין מכתיר את הפסגה.**","5142f236":"ואז הגיע האביב, מספר *Landnámabók*: **שור אחד** — אז **האירים המשועבדים שלו גררו את המחרשה**. הם הרגו את השור ו**האשימו דוב**. באיסלנד **אין דובים** — פשוט המתיישבים החדשים עוד לא ידעו את זה. כשהנורדים התפזרו לצוד אותו, העבדים **ארבו להם אחד-אחד**, כולל ל-Hjörleifur, ואז ברחו עם הנשים והסירות לאיים שממול.","4d0fd264":"Ingólfur מצא את הגופות, עקב אחרי הרוצחים עד לאיים האלה, והרג את כולם. ההספד שלו: **“סוף עצוב לאיש טוב, שנרצח בידי עבדים — זה מה שקורה כשמסרבים להקריב קורבן.”** האיים האלה הפכו ל-**Vestmannaeyjar** — **“איי אנשי המערב,”** השם הנורדי ל**גאלים אירים** — **קרויים על שם המשועבדים שביצעו את המעשה.**","1b4a5342":"הרוח הגיעה **שלוש מאות שנה אחר כך**. **Katla**, סוכנת בית מפחידה במנזר הסמוך **Þykkvabæjarklaustur**, הייתה בעלת **מכנסי קסם שלא מתעייפים לעולם**. הרועה **Barði** שאל אותם; היא **הטביעה אותו בחבית מי הגבינה**. כשמפלס מי הגבינה ירד ואיים לחשוף את הגופה, היא ברחה אל **Mýrdalsjökull** ו**קפצה לתוך התהום שעדיין נקראת Kötlugjá — “הבקע של Katla”** — הפתח של הר הגעש. זמן קצר אחר כך **פרץ שיטפון קרחוני מתוך הקרח**. **הר הגעש קרוי על שמה** — ואומרים שכל התפרצות היא מזג הרוח שלה.","cca9787f":"כמו Pétursey, גם הכף הזה **היה פעם אי** — וקשור היום לאיסלנד במיילים של חול שחור של Katla.","bd9240a0":"“איי אנשי המערב”","1941fbd6":"הר הגעש וסוכנת הבית","d7c53f11":"הבקע של Katla — התהום שאליה היא קפצה","6591c611":"הקרחון שמעל הר הגעש","9623a474":"המנזר","91d6f025":"נער הרועים","20eb72f4":"Skógafoss","dabe8779":"ב-Skógafoss.","f5ddbd46":"נקודה אחת: קווי חוף עתיקים, sandur מודרני, חוות ישנות, שביל של הרי געש, ותיבה נעלמת שמישהו תפס בה את החלק הלא נכון.","5b304623":"אם זה היה בכל מקום אחר, זה היה האירוע המרכזי. כאן זו סתם **עוד עצירה ביום שלישי**.","540c44d6":"נהר **Skógá** מדלג על האשדות ופשוט צועד ישר מעל מצוק הים הישן — **נפילה נקייה של 60 מ׳, ברוחב 25 מ׳** — נפילה חופשית לתוך בריכה עמוקה, ואז מרוץ על פני ה-sandur עד האטלנטי. בתחתית **צריך לצעוק כדי שישמעו אתכם**, ולכן רוב הסרטונים מכאן הם אנשים שמצביעים בשקט.","131a1c27":"המצוק הזה הוא **קו החוף מלפני אלפי שנים**: גיאולוגיה של מפלים ישר מספר הלימוד — סלע כיסוי קשה מעל סלע רך, חתירה מלמטה והתמוטטות, ולכן המפל אוכל את עצמו **במעלה הזרם** ומשאיר מאחוריו ערוץ. מאז היבשה עלתה, הנהרות שפכו חול שחור, וקו החוף האמיתי צעד כמה ק״מ דרומה — **ו-Skógafoss לא זז מילימטר.**","0814aff3":"גרם המדרגות ממתכת מימין הוא מבחן הכושר החינמי שלכם; ולמעלה מתחיל **שביל Fimmvörðuháls**, שמטפס **בין Eyjafjallajökull ל-Mýrdalsjökull** — בדיוק אותו רווח שההתפרצות של 2010 פתחה בו סדק ראשון.","9eac0459":"מאחורי החניון: **מוזיאון Skógar** (בתי כבול, כנסייה עתיקה, מבני חווה) ו**מפל בונוס, Kvernufoss**, שמסתתר בערוץ ירוק ממש ליד. ובנוסף האגדה על **האוצר של Þrasi** — תיבת זהב של מתיישב שהוחבאה מאחורי המפל. שודדים לעתיד תפסו בטבעת הברזל של התיבה, אבל היא פשוט **נשברה**; הטבעת ההיא הייתה תלויה על **דלת הכנסייה עד 1890** והיום היא במוזיאון. הזהב, מן הסתם, עדיין מאחורי המים.","ab00ce23":"המתיישב עם האוצר","c621cc3e":"שביל הרי הגעש","d9e3d1ff":"כיפת הקרח","955b6221":"המוזיאון / הכפר","e9026c71":"מפל הבונוס המוסתר","19e69339":"Seljalandsfoss","b3e34062":"Seljalandsfoss ו-Gljúfrabúi","c61a4354":"בחניון של Seljalandsfoss.","8a7b8047":"אותו מצוק. אותו קו חוף מעידן הקרח. **שינוי זעיר אחד בסלע** = שתי אישיויות מפל שונות לגמרי.","4d3488da":"תעמדו מול מצוק הים הישן. תלכו מאחורי המפל. אם נשארו לכם גרביים יבשות אחרי Gljúfrabúi, עשיתם משהו לא נכון.","2e69a0e5":"**Seljalandsfoss** נופל **60 מ׳** נקיים ממצוק הים הישן של איסלנד, ומוזן מנהר **Seljalandsá** שיורד מקרחון **Eyjafjallajökull** שמעל.","a32bccc7":"גומחה טבעית מאפשרת לכם ללכת **עד מאחורי מסך המים** בקיץ — סלע רטוב וחלקלק, אז נעליים טובות, מעיל אטום לגשם ו**יד אחת פנויה**; כשיש קרח השביל נסגר, אז תכבדו את המחסום.","050db2f6":"המצוק הזה הוא **מצוק ים ישן, ממש מיד אחרי עידן הקרח**, כשהאטלנטי הגיע עד למרגלות **Eyjafjöll**; אחר כך הנהרות מילאו את השפלה, וקו החוף נמצא היום כמה ק״מ דרומה — בדיוק אותו קו חוף שהוצף ואז ננטש כמו ב-Skógafoss שבהמשך הדרך. הים הלך, המפלים נשארו.","b0b44da2":"הליכה קצרה צפונה, **Gljúfrabúi** (“דייר הקניון”) מסתתר בערוץ צר ומכוסה אזוב — רק הראש שלו מציץ החוצה; כדי לפגוש אותו **צריך לבוסס במעלה הנחל**, ו**רגליים רטובות זה לא נתון למשא ומתן.**","f2e7980a":"רכס ההרים","3dc09caa":"Hvolsvöllur → Skógafoss","35acc3ee":"Skógafoss → Reynisfjara","682884c7":"תסתכלו ימינה בשעה 2 — הרחק על Sólheimasandur.","af91d688":"תסתכלו מזרחה בשעה 9–10 — ההר העצום עם הפסגה השטוחה באופק.","45436686":"בחניון של Sólheimajökull."};
